var HOWTO = {"neon-demon-hunter": {"m": ["Black hoodie, black pants, chunky sneakers, 1 set (own)", "Neon fabric paint in 2 to 3 colors, 1 tube each (buy: craft store)", "Glow-in-the-dark temporary tattoos or neon eyeliner, 1 pack (buy: drugstore)", "Toy sword prop, 1 (buy: toy store)", "Hair gel or temporary neon hair spray, 1 (buy: drugstore)", "Black leather-look jacket or vest, 1 (buy: thrift store, optional)"], "s": ["Buy the neon fabric paint, temporary tattoos, toy sword prop, and hair spray. Lay the black hoodie, black pants, and chunky sneakers flat.", "Sketch the demon-slaying symbols on paper FIRST. Crooked symbols cannot be unpainted. Draw sharp neon symbols on the hoodie sleeves and pant legs with the fabric paint. Let dry 2 hours.", "Style the hair up with hair gel, or mist it with the temporary neon hair spray. Apply the neon eyeliner or glow-in-the-dark temporary tattoos on the cheeks and arms.", "Wear the black leather-look jacket over the hoodie and carry the toy sword prop. Keep the painted side facing out so the neon sigils show.", "Optional pro finish: charge the neon paint under bright light before heading out, and add one glowing green 'scar' across the cheek with face paint. The scar is the backstory, everyone will ask about it.", "Optional pro finish: charge the neon paint under bright light before heading out, and add one glowing green 'scar' across the cheek with face paint. The scar is the backstory, everyone will ask about it."]}, "classic-ghost": {"m": ["1 white flat sheet: twin size for kids under 8, full size for tweens and adults (make: use an old sheet; buy: thrift store for a dollar or two)", "Black marker, thick tip, 1 (buy: dollar store)", "Scissors, 1 pair", "2 small squares of black tulle or sheer fabric, about 4 inches each (optional, for see-through eyes; buy: craft store)"], "s": ["Pick the sheet size first: twin flat for a small kid, full for a bigger kid or adult. Bigger than you need is fine; smaller is not.", "Drape the sheet over the wearer and have them stand still. Mark both eye spots with the black marker while the sheet is on, marking blind never lines up.", "Take the sheet off. Cut the eye holes SMALL first, about the size of a quarter. You can always widen them; you cannot shrink them.", "Hold the sheet up and check: the wearer should see clearly through both holes. Widen a little at a time until they can.", "Optional pro finish: tape a square of black tulle behind each hole. From outside the eyes look dark and hollow; from inside you see straight through the mesh.", "Safety: trim the bottom so the hem clears the ground by several inches, a dragging hem is what trips a kid on a dark sidewalk. Keep nothing tight around the neck.", "Draw a wavy or smiling mouth below the eyes with the black marker. Drape it back on and go."]}, "blue-dog-family": {"m": ["Blue or orange t-shirt per person, 1 each (own, or buy: clothing store)", "Headband per person, 1 each (buy: dollar store)", "Blue, orange, and white craft felt, 1 sheet of each color 9x12 inches (buy: craft store, construction paper works too)", "Safety pins, 4 per person (buy: dollar store)", "Scissors, 1 pair"], "s": ["Buy the t-shirts, headbands, craft felt, and safety pins.", "Cut one paper ear template and check it against the headband before cutting felt. Cut two floppy dog ears from the craft felt with the scissors for each person, about 5 inches long. Match ear color to shirt color.", "Pin the ears to each headband with the safety pins.", "Pin a white craft felt belly spot to the front of each blue or orange t-shirt.", "Pull on the blue or orange t-shirts.", "Put on the headbands and decide who is mama, dad, and the pups.", "Optional pro finish: stuff an old sock with tissue, pin it to the back waistband as a tail, and let it wag. Every dog family photo is better with a tail.", "Optional pro finish: stuff an old sock with tissue, pin it to the back waistband as a tail, and let it wag. Every dog family photo is better with a tail."]}, "superhero-family": {"m": ["Matching red sweatsuits, 1 per person (own: from closet, or buy a set at a discount store)", "Black felt, 1 pack (buy: craft store; construction paper works too)", "Yellow felt, 1 sheet (buy: craft store)", "Plain headbands, 1 per person (buy: dollar store multi-pack)", "Safety pins, 6 to 8, or tape, 1 roll (own: from home)", "Scissors, 1 pair (own: from home)"], "s": ["Buy the felt sheets and headbands.", "Have everyone dress in the red sweatsuits.", "Safety: cut the eye holes wide enough so everyone can see clearly.", "Trace the eye holes by holding the felt strip up to each face and marking the pupil spots. Cut the eye holes SMALLER than the marks first and widen as needed, since cut felt cannot be uncut. Make the eye masks: cut a mask strip from the black felt for each person with two eye holes. Attach it to the headband with the safety pins or tape.", "Make the logos: cut one big first-initial letter per person from the yellow felt. Use the safety pins or tape to attach it to the chest of each sweatsuit.", "Everyone wears the mask headband with the letter on the chest. Each person strikes their own hero pose for the group photo.", "Optional pro finish: cut a small yellow felt lightning bolt and pin one to each sleeve, so the emblem repeats beyond the chest.", "Optional pro finish: cut a small yellow felt lightning bolt and pin one to each sleeve, so the emblem repeats beyond the chest."]}, "blue-alien-ohana": {"m": ["Blue hoodie per alien-role person, 1 each (own, or buy: clothing store)", "Blue craft felt, 1 sheet 9x12 inches per alien (buy: craft store, construction paper works too)", "Headband per alien-role person, 1 each (buy: dollar store)", "Red t-shirt or dress per Lilo-role person, 1 each (make: from closet, or buy: thrift store)", "White craft felt or paper, 1 sheet (buy: craft store)", "Safety pins, 4 to 6 (buy: dollar store)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the blue craft felt, the headbands, the white felt or paper, and the safety pins.", "Cut one paper ear template first and hold it against the headband to check the size, alien ears should be tall, about 6 inches. Then cut two large oval ears from the blue craft felt for each alien-role person with the scissors.", "Tape one pair of ears to each headband with the tape.", "Pull on the blue hoodies.", "Lilo: cut leaf shapes from the white felt or paper with the scissors. Pin or glue the leaves across the red t-shirt or dress.", "Safety: pin from the front of the red shirt, so pin backs face the fabric and never the skin.", "Wear dark hair down for Lilo. Put the ear headbands on the aliens last.", "Optional pro finish: cut a smaller pink felt oval and glue it inside each blue ear. The inner ear is the detail that makes people recognize the character instead of just 'blue alien'.", "Optional pro finish: cut a smaller pink felt oval and glue it inside each blue ear. The inner ear is the detail that makes people recognize the character instead of just 'blue alien'."]}, "emerald-witch": {"m": ["1 long green dress, or green fabric, 3 yards (buy: fabric store)", "1 sheet black cardboard, 22x28 inches, for the hat (buy: craft store; a box painted black works too)", "Green face paint, non-toxic, 1 tube (buy: drugstore)", "Black eyeliner, 1, and dark green eye shadow, 1 (buy: drugstore)", "Hot glue gun with glue sticks, 1 set and scissors, 1 pair", "1 broom from home for a prop (make: use what you own)"], "s": ["Buy the green fabric, black cardboard, green face paint, black eyeliner, and dark green eye shadow.", "Safety: let an adult handle the hot glue, since the nozzle and glue get very hot.", "Sew or hot glue the green fabric into a long gown, leaving the hem ragged.", "Measure the head first, then roll the black cardboard into a tall cone and tape it loosely to check the fit before gluing. Glue a wide cardboard brim to its base with the hot glue. Hot glue sets fast and cannot be repositioned, so test the cone shape dry first.", "Paint the face green with the green face paint. Draw on the black eyeliner and the dark green eye shadow.", "Carry the broom bristle-up so it does not trip anyone.", "Optional pro finish: fray the gown hem by cutting 2-inch slits every few inches. A ragged hem is the difference between green dress and witch's gown.", "Optional pro finish: fray the gown hem by cutting 2-inch slits every few inches. A ragged hem is the difference between green dress and witch's gown."]}, "gloom-bloom": {"m": ["1 set black clothes from the closet (make: use what you own)", "1 set colorful clothes from the closet (make: use what you own)", "Black and white face paint, non-toxic, 1 set (buy: drugstore)", "2 hair ties for braids (make: use what you own)", "3 to 5 fake flowers (buy: dollar store; paper flowers work too)"], "s": ["Buy the black and white face paint and the fake flowers.", "Gloom: wear the black clothes, and braid the hair tightly with the hair ties.", "Paint a small black teardrop under one eye with the black and white face paint.", "Bloom: wear the colorful clothes, and pin the fake flowers in the hair.", "Paint a small flower on one cheek with the face paint, keeping it clear of the eyes.", "Stand side by side: Gloom frowns and looks away, Bloom smiles big.", "Optional pro finish: braid the gloom hair tight with a middle part, and pin the bloom flowers all on one side. Opposite styling is what makes the pair read as opposites.", "Optional pro finish: braid the gloom hair tight with a middle part, and pin the bloom flowers all on one side. Opposite styling is what makes the pair read as opposites."]}, "deadpan-diva": {"m": ["Black dress, 1 (own)", "Very pale foundation or white non-toxic face paint, 1 (buy: toy store)", "Dark eyeliner and lipstick, 1 set (own, or buy: dollar store)", "2 hair ties (own)"], "s": ["Braid the hair into two tight braids with the hair ties.", "Buy the white non-toxic face paint if needed.", "Test the pale foundation on the jawline first and blend fully, patchy pale makeup reads as sick, not deadpan. Apply the pale foundation evenly over the face, blending into the neck so there is no mask line.", "Add the dark eyeliner and lipstick for contrast.", "Put on the black dress, fold the arms, and hold the stare.", "Use skin-safe makeup and wash it all off before bed.", "Optional pro finish: add a thin black ribbon choker. The choker plus the braids plus the stare is the complete silhouette, without it, it is just a black dress.", "Optional pro finish: add a thin black ribbon choker. The choker plus the braids plus the stare is the complete silhouette, without it, it is just a black dress."]}, "safari-zoo-crew": {"m": ["Solid-color clothes in animal colors, 1 set per person (own)", "Plastic headbands, 1 per person (buy: dollar store multi-pack)", "Felt sheets in brown, black, pink, tan, 1 pack (buy: craft store; construction paper works too)", "Face paint in brown and black, 1 tube each (buy: costume aisle or craft store)", "Scissors and tape, 1 set (own)"], "s": ["Assign roles BEFORE building. One guide per three animals keeps the ratio fun. Each person picks one animal and pulls matching solid-color clothes from the closet.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Make each animal's ears from felt: cut two rounded ears and tape them to a plastic headband.", "Safety: use non-toxic kids face paint, and keep it away from the eyes.", "Paint faces: use the face paint to add each animal's nose, whiskers, or spots.", "Wear the colored outfit and put on the ear headband. Add one felt detail, like a felt tail taped to the back, to complete each animal.", "Optional pro finish: the guide 'discovers' each animal with the binoculars throughout the night, announcing the species dramatically. The discovery bit is the group performance.", "Optional pro finish: the guide 'discovers' each animal with the binoculars throughout the night, announcing the species dramatically. The discovery bit is the group performance."]}, "fairy-tale-princesses": {"m": ["1 dress from the closet per person (make: use what you own)", "1 cereal box per crown (make: from a cereal box)", "Gold or silver paint or markers, 1 set (buy: craft store)", "Scissors, 1 pair and tape, 1 roll", "1 hair ribbon per person (buy: dollar store)"], "s": ["Buy the gold or silver markers and the hair ribbon.", "Each princess picks any dress from her own closet.", "Safety: adults handle the scissors when cutting the cardboard crowns.", "Draw the crown shape on the cereal box in pencil first and hold it against the head to check the fit. Cut the crown with the scissors, leaving a 1-inch tab to tape the ends together. Color it with the gold or silver paint or markers and let it dry.", "Tie the hair ribbon as a bow, and tape the cardboard crown on top of the head.", "Line up for a princess parade photo, and check that each cardboard crown sits snugly.", "Optional pro finish: tie the ribbon as a bow under the crown, not on top. The bow peeking out below the crown looks styled; on top it looks like wrapping.", "Optional pro finish: tie the ribbon as a bow under the crown, not on top. The bow peeking out below the crown looks styled; on top it looks like wrapping."]}, "tin-hero": {"m": ["Red sweatsuit, 1 (own)", "Gold duct tape, 1 roll (buy: dollar store or hardware store)", "Battery tea light, 1 (buy: dollar store)", "Cardboard, 1 piece (own)", "Tape, 1 roll (own)", "Safety pin, 1 (own)"], "s": ["Buy the gold duct tape and the battery tea light.", "Dress in the red sweatsuit.", "Stripe the sweatsuit with the gold duct tape: strips across the chest, arms, and legs.", "Draw the reactor circle on the cardboard BEFORE cutting, and measure it against the chest first. Cover it in gold tape, then tape the tea light behind its center.", "Safety: pin from inside the sweatsuit, so the pin back faces the fabric and never the skin.", "Pin the glowing circle to the chest of the sweatsuit.", "Walk like the suit does the talking.", "Optional pro finish: pin the reactor slightly off-center, like battle damage. Perfectly centered reads as costume; off-center reads as character.", "Optional pro finish: pin the reactor slightly off-center, like battle damage. Perfectly centered reads as costume; off-center reads as character."]}, "good-witch-bad-witch": {"m": ["1 black dress or set of black clothes for the bad witch (make: use your closet)", "1 pink dress or set of pink clothes for the good witch (make: use your closet)", "Green face paint, non-toxic, 1 tube (buy: drugstore)", "1 cardboard crown (make: from a cereal box)", "1 black cone hat (buy: dollar store)", "Hot glue gun, scissors, 1 pink marker, tape"], "s": ["Buy the green face paint, the black cone hat, and the pink marker.", "Bad witch: wear the black dress or black clothes.", "Safety: let an adult handle the hot glue, and keep the green face paint away from the eyes.", "Test the hat brim bend dry before gluing: fold the brim, check it in a mirror, then hot glue it. Hot glue sets in seconds and cannot be repositioned. Paint the bad witch's face and hands green with the green face paint, keeping paint away from the eyes and patch-testing sensitive skin first.", "Good witch: wear the pink dress or pink clothes. Color the cardboard crown with the pink marker, and tape it on the head.", "Optional pro finish: color the cardboard crown with the pink marker on both sides. A double-sided crown flashes pink in photos; single-sided flashes brown cardboard.", "Optional pro finish: color the cardboard crown with the pink marker on both sides. A double-sided crown flashes pink in photos; single-sided flashes brown cardboard."]}, "fuzzy-monster": {"m": ["1 pastel fuzzy sweatsuit (buy: discount store)", "2 large googly eyes, 3 inches or bigger (buy: craft store; paper circles work too)", "1 sheet white felt, 9x12 inches, for the smile (buy: craft store; construction paper works too)", "Scissors, 1 pair", "Fabric glue, 1 tube, or 4 safety pins"], "s": ["Buy the pastel fuzzy sweatsuit, the googly eyes, and the white felt.", "Glue or pin the two googly eyes to the hood of the pastel fuzzy sweatsuit.", "Safety: adults handle the scissors when cutting the white felt.", "Draw the smile on paper first and hold it against the sweatsuit chest to check the size: it should span most of the chest. Cut the stitched-style smile from the white felt with the scissors. Cut it bigger than feels right: small smiles disappear into the fuzz.", "Let the fabric glue dry fully before wearing.", "Wear the hood up so the googly eyes sit above the forehead.", "Optional pro finish: cut two small felt fangs and glue them at the smile's corners. Fangs turn a friendly monster into a funny one.", "Optional pro finish: cut two small felt fangs and glue them at the smile's corners. Fangs turn a friendly monster into a funny one."]}, "pocket-plush": {"m": ["Fuzzy one-piece pajamas or sweatsuit, 1 (buy: thrift store, or own: from closet)", "Felt ears: two big felt circles, about 4 inches across (buy: craft store; construction paper works too)", "Fabric glue, 1 tube (buy: craft store)", "Black and white felt for eyes and smile, 1 small sheet each (buy: craft store; paper works too)", "Large shipping tag or big index card, 1 (buy: office supply store)", "Marker, 1 (own: household)"], "s": ["Buy the fuzzy one-piece pajamas, felt ears, fabric glue, and large shipping tag. Glue the felt ears to the hood of the fuzzy one-piece pajamas.", "Cut the eyes and smile from paper first and lay them on the pajama chest to check the size and spacing, glued felt cannot be repositioned. Then cut two white felt eyes and a stitched-look smile from the black felt, and glue them to the chest of the fuzzy pajamas with the fabric glue.", "Write a collector number like 'No. 001' on the large shipping tag with the marker. Tie the tag to the wrist or waistband with string.", "Wear the fuzzy one-piece pajamas with the felt ears and large shipping tag showing. The smile goes on the chest like a plush's embroidered face.", "Optional pro finish: stitch the smile with dashed lines using a white fabric marker instead of a solid line. Dashed stitches read as plush embroidery; a solid line reads as a drawing.", "Optional pro finish: stitch the smile with dashed lines using a white fabric marker instead of a solid line. Dashed stitches read as plush embroidery; a solid line reads as a drawing."]}, "soccer-squad": {"m": ["Matching jerseys or same-color t-shirts, 1 per player (own: from closet, or buy a multi-pack at a sports store)", "Black shirt and black shorts for the referee, 1 set (own: from closet)", "Soccer ball, 1 any size (buy: sports store, or borrow from home)", "Red cardstock rectangle, 3x4 inches, 1 (own: cut from a folder or colored paper)", "Black marker, 1 (own: from home)", "White athletic tape, 1 roll (buy: sports store or pharmacy)", "Scissors, 1 pair"], "s": ["Assign roles: most of the family are players, one person is the referee.", "Players: wear matching jerseys or same-color shirts. Wrap a strip of white athletic tape around one upper arm as a captain's armband. Referee: wear all black.", "Safety: cut the cardstock slowly and keep fingers clear of the scissors.", "Cut the red cardstock rectangle a little larger than 3x4 inches first, then trim to size after holding it up to check it reads at arm's length. Make the red card: cut the rectangle from the folder or colored paper. Draw a thick black border around it with the black marker so it reads as a card at a glance.", "Players carry or dribble the soccer ball. The referee practices holding the red card high in the air.", "Optional pro finish: give the referee a coin for the coin toss and a small notebook as the official match log.", "Optional pro finish: give the referee a coin for the coin toss and a small notebook as the official match log."]}, "glow-skeleton": {"m": ["Black sweatsuit, 1 (buy: discount store, or own)", "Glow-in-the-dark bone tape, 1 roll (buy: craft store)", "Glow bracelets, 1 pack (buy: dollar store)", "Scissors, 1 pair", "Black face paint, non-toxic, 1 tube (buy: drugstore)"], "s": ["Buy the black sweatsuit if you do not own one, plus the bone tape and glow bracelets.", "Charge the bone tape under a lamp for 20 minutes for maximum glow.", "Safety: adults handle the scissors when cutting the bone tape.", "Cut the bone tape into rib bones: lay strips horizontally across the chest and back. Add vertical spine segments down the center, and arm and leg bones down the limbs.", "Snap the glow bracelets onto both wrists and both ankles right before heading out.", "Test the face paint on the wrist first and wait 10 minutes for any reaction. Paint simple skull eye circles with the black face paint, keeping clear of the eyes so vision stays clear.", "Optional pro finish: 'charge' the glow tape under a bright lamp for 10 minutes right before heading out. Freshly charged tape glows dramatically for the first hour, that is when the photos happen.", "Optional pro finish: 'charge' the glow tape under a bright lamp for 10 minutes right before heading out. Freshly charged tape glows dramatically for the first hour, that is when the photos happen."]}, "block-game-crew": {"m": ["1 large cardboard box per person, big enough to fit over the torso (make: ask a grocery store for spares)", "Acrylic paint in each hero's colors, 1 small bottle per color (buy: craft store, tempera paint works too)", "Paintbrushes, 1 wide and 1 detail per person", "Black marker, 1 (buy: dollar store)", "Scissors, 1 pair"], "s": ["Each person picks a blocky video-game hero look.", "Safety: an adult should handle the heavy cutting, and cut the eye holes generously so everyone can see clearly.", "Measure each person's head and shoulders first, then cut a head opening and eye holes in each large cardboard box with the scissors. Cut the head opening smaller than you think, cardboard cut away cannot be put back. Cut the eye holes generously so everyone can see clearly.", "Paint each box in the hero's main colors with the acrylic paint and paintbrushes. Let it dry fully.", "Draw a pixel-style square face and details on the front of each box with the black marker. Wear the boxes over regular clothes once the paint is dry.", "Optional pro finish: draw thin black grid lines across the painted box before it dries fully. The grid is what makes it read as pixels instead of just a painted box.", "Optional pro finish: draw thin black grid lines across the painted box before it dries fully. The grid is what makes it read as pixels instead of just a painted box."]}, "web-slinger-crew": {"m": ["Hoodies in red, black, and pink, 1 per person (own: from closet)", "Black fabric paint or black face paint, 1 tube (buy: craft store)", "White stickers or white electrical tape, 1 roll (buy: hardware store)", "Sunglasses or swim goggles, 1 per person (buy: dollar store multi-pack)", "Tape, 1 roll (own: from home)"], "s": ["Assign each person a hoodie color.", "Buy the black fabric paint or black face paint, white stickers or white electrical tape, and the multi-pack of sunglasses.", "Draw the eye-lens shape on paper first and hold it against the sunglasses to check the size before painting, since paint on lenses cannot be removed cleanly. Stick white stickers or white electrical tape in a web pattern across the front of each pair of sunglasses. Draw two black eye lenses on top with the black fabric paint or black face paint. Let them dry flat for 30 minutes.", "Make the chest webs: stick short white tape strips in a web grid across the chest of each hoodie.", "Wear the hoodie with the hood up and put on the web-patterned sunglasses. Each person picks their own web-shooting pose for the group shot.", "Optional pro finish: run short white tape strips down the outside of each sleeve as web lines, so the arms match the chest.", "Optional pro finish: run short white tape strips down the outside of each sleeve as web lines, so the arms match the chest."]}, "mermaid-crew": {"m": ["T-shirt or dress in a sea color (teal, purple, red, white), 1 per person (buy: thrift store, or own)", "Face paint in a matching accent color, 1 tube (buy: drugstore)", "Plastic trident prop, 1 (buy: toy store)", "Toy crab or red paper for a cardboard crab, 1 (make: cut from red paper, or buy: toy store)", "Shell necklace, 1 (buy: craft store, or make: string pasta shells)", "Scissors and tape, 1 set (own)"], "s": ["Buy the plastic trident prop and the face paint. Assign each person a role and a sea-colored t-shirt or dress from the closet.", "Sketch the cheek detail on paper first. Face paint is hard to remove and redo once applied. Paint one small matching detail per person: scales on a cheek, a seaweed swirl, or an anchor.", "Cut a red paper body, legs, and claws with the scissors and tape them to the smallest person's shirt. Or hand them the toy crab instead.", "The sea king carries the plastic trident prop. Everyone else picks one accessory, like the shell necklace, and stands tall for the crew photo.", "Optional pro finish: dab the accent face paint along the cheekbones through a fishnet stocking as a stencil. The scale stencil photographs like movie makeup.", "Optional pro finish: dab the accent face paint along the cheekbones through a fishnet stocking as a stencil. The scale stencil photographs like movie makeup."]}, "little-pig-family": {"m": ["Pink t-shirts or pajamas, 1 per person (buy: thrift store, or own: from closet)", "Pink headband, 1 per person (buy: dollar store)", "Pink paper cup, 1 per snout (own: from the kitchen drawer)", "Pink felt or construction paper, 2 triangles per ear (buy: craft store)", "Pink string or yarn, 1 arm length per snout (own: from the craft drawer)", "Scissors, 1 pair, and clear tape, 1 roll (own: household tools)", "Pink blush or face paint for cheeks, 1 (buy: drugstore)"], "s": ["Buy the pink t-shirts and pink headbands. Gather the pink paper cups, pink felt, pink string, scissors, and clear tape from around the house.", "Poke the holes SMALL first with the scissor tip and test the string fit, holes poked too big tear through the cup and the snout falls apart. Poke two small holes in the sides of a pink paper cup.", "Cut one paper ear template first and check the size on the headband, ears should stand about 3 inches tall. Then cut two pink felt triangles with the scissors and tape them to the pink headband as ears.", "Thread the pink string through the holes, then tie the cup gently in front of the nose.", "Dab a little pink blush on each person's cheeks with a finger. Hand the little brother a toy dinosaur from the toy store or one he owns. Now he is the pig who brings the dinosaur.", "Optional pro finish: draw two small black nostril dots on the bottom of each cup snout with a marker. Nostrils are the detail that turns a taped cup into a snout.", "Optional pro finish: draw two small black nostril dots on the bottom of each cup snout with a marker. Nostrils are the detail that turns a taped cup into a snout."]}, "enchanted-castle-crew": {"m": ["Princess: yellow fabric, 2 yards (buy: fabric store)", "Prince: 1 blue jacket and 1 pair dark pants (make: use your closet)", "Candelabra: gold face paint, 1 tube, and 1 gold headband (buy: craft store)", "Clock: 1 brown cardboard circle, about 12 inches, and painted hands (make: from a box)", "Teapot: 1 white pot or cardboard pot body (make: from a box)", "Hot glue gun, 1; scissors, 1 pair; face paint, 1 set"], "s": ["Buy the yellow fabric, gold face paint, and gold headband. Assign roles first so nobody builds the same prop twice.", "Princess: wrap and pin the yellow fabric as a simple gown. Prince: wear the blue jacket and dark pants with a sash of torn fabric.", "Safety: let an adult handle the hot glue, and keep the face paint away from the eyes.", "Cut three flame shapes from cardboard first and arrange them dry on the gold headband to check the spacing. Glue them with the hot glue. Hot glue sets in seconds and cannot be repositioned, so the dry layout is the whole step.", "Safety: adults handle the scissors when cutting the cardboard.", "Clock: paint the brown cardboard circle cream and add painted hands. Teapot: cut a rounded cardboard pot body, add a handle and spout, and wear it over the shoulders.", "Optional pro finish: add a red fabric sash to the prince's blue jacket. The sash is the one detail that turns jacket-and-pants into royalty.", "Optional pro finish: add a red fabric sash to the prince's blue jacket. The sash is the one detail that turns jacket-and-pants into royalty."]}, "bumble-bee": {"m": ["Black sweatshirt and sweatpants, 1 set (own, or buy: clothing store)", "Yellow duct or electrical tape, 1 roll (buy: dollar store)", "Black headband, 1 (buy: dollar store)", "2 yellow pipe cleaners, 12 inches each (buy: craft store, floral wire works too)", "2 black pom-poms, 1 inch (buy: craft store, cotton balls work too)", "Craft glue, 1 tube (buy: craft store)"], "s": ["Buy the yellow duct or electrical tape, black headband, yellow pipe cleaners, black pom-poms, and craft glue.", "Mark stripe positions with chalk or a light pencil first so the spacing is even. Wrap three yellow duct tape stripes around the torso of the black sweatshirt and one around each arm, even spacing is what makes it read as bee instead of random tape.", "Twist the two yellow pipe cleaners into a V.", "Safety: use non-toxic craft glue, and keep the pom-poms out of reach of toddlers.", "Glue a black pom-pom to each tip of the V with the craft glue. Glue the base of the V to the black headband.", "Let the glue dry fully, then pull on the black sweatshirt and sweatpants and the black headband.", "Optional pro finish: cut two white ovals from a plastic bag and tape them to the back as wings. Bees have wings; the ten seconds it takes doubles the recognition.", "Optional pro finish: cut two white ovals from a plastic bag and tape them to the back as wings. Bees have wings; the ten seconds it takes doubles the recognition."]}, "baby-dino": {"m": ["Green hoodie, 1 (buy: clothing store, or use your own)", "2 sheets green craft felt, 9x12 inches each (buy: craft store, construction paper works too)", "Pillow stuffing or 2 old socks (make: stuff from home)", "Safety pins, 6 to 8 (buy: dollar store)", "Masking tape, 1 roll", "Scissors, 1 pair"], "s": ["Buy the green hoodie, green craft felt, and safety pins.", "Cut a paper triangle template first and test the size on the hoodie. Then cut 6 to 8 triangle spikes from the green craft felt with the scissors, spikes cut too small look lost on the back, so go palm-size.", "Tape the spikes in a row down the back of the green hoodie with the masking tape. Pin each spike from inside the hoodie with a safety pin.", "Stuff the old socks with the pillow stuffing and tape the open ends shut with the masking tape.", "Safety: pin everything from inside the green hoodie, so pin backs face the fabric and never the skin.", "Pin the stuffed tail to the back waistband of the green hoodie.", "Optional pro finish: cut two small white felt triangles and pin them to the hoodie cuffs as claws. Claws sell the dinosaur more than the spikes do.", "Optional pro finish: cut two small white felt triangles and pin them to the hoodie cuffs as claws. Claws sell the dinosaur more than the spikes do."]}, "little-lion": {"m": ["Tan or brown sweatsuit, 1 (buy: discount store, or use one you own)", "Brown fuzzy fabric strip or old brown towel for the mane, about 24 inches long (buy: fabric store, or make: cut from a towel)", "Scissors, 1 pair (own)", "Safety pins or fabric glue, 6 to 8 pins or 1 tube glue (buy: dollar store or craft store)", "Brown non-toxic face paint, 1 tube (buy: drugstore)"], "s": ["Buy the tan sweatsuit and the brown fuzzy fabric strip.", "Safety: adults handle the scissors when cutting the brown fuzzy fabric.", "Cut a paper collar template first and test it around the sweatsuit hood, a mane cut too small looks like a bib, and fuzzy fabric cut away cannot be put back. Then cut the brown fuzzy fabric into a wide collar for the mane, cutting generous and trimming after the fitting.", "Pin the mane around the hood or neckline of the tan sweatsuit with the safety pins, fluffing it outward.", "Paint a brown nose and whiskers with the brown face paint, keeping clear of the eyes.", "Pin the mane flat at the back so it does not slip over the eyes while the little lion runs.", "Optional pro finish: cut a small triangle tail from the leftover fuzzy fabric and pin it to the back waistband. The tail is what other kids point at.", "Optional pro finish: cut a small triangle tail from the leftover fuzzy fabric and pin it to the back waistband. The tail is what other kids point at."]}, "tiny-firefighter": {"m": ["Red sweatsuit, 1 (own: from closet)", "Toy firefighter helmet, 1 (buy: toy store)", "Toy fire hose or coiled garden hose, 1 (buy: toy store, or borrow a real coil of rope from home)", "Yellow reflective tape, 1 roll (buy: hardware store)", "Black marker, 1 (own: from home)"], "s": ["Buy the toy firefighter helmet, toy fire hose, and yellow reflective tape. Dress the kid in the red sweatsuit.", "Make the turnout stripes: wrap two horizontal bands of the yellow reflective tape around each sleeve and each leg. Press the tape firmly so it sticks.", "Safety: keep the toy firefighter helmet snug so it does not slide over the eyes.", "Put the toy firefighter helmet on and carry the toy fire hose coiled over one shoulder.", "Finishing touch: the kid holds the hose nozzle out front for the hero photo.", "Optional pro finish: wrap one band of reflective tape around the toy helmet too, so the whole uniform matches.", "Optional pro finish: wrap one band of reflective tape around the toy helmet too, so the whole uniform matches."]}, "little-shark": {"m": ["Gray hoodie, 1 (buy: thrift store, or own: from closet)", "Gray felt, 1 sheet 9x12 inches (buy: craft store; construction paper works too)", "White felt, 1 small sheet (buy: craft store; white paper works too)", "Fabric glue, 1 tube (buy: craft store)", "Scissors, 1 pair (own: household tools)"], "s": ["Buy the gray hoodie, gray felt, and white felt from the craft store. Gather the scissors and fabric glue.", "Cut a paper fin template first and hold it against the hoodie back, a fin cut too small disappears on the hoodie, and felt cut away cannot be put back. Then cut a triangle fin about 8 inches tall from the gray felt, and a jagged row of teeth from the white felt.", "Glue the teeth inside the hood edge of the gray hoodie so they show around the face.", "Glue the fin to the back of the gray hoodie, low between the shoulders.", "Let the fabric glue dry flat for 30 minutes.", "Zip the gray hoodie over a white t-shirt and pull the hood up for the shark face.", "Optional pro finish: glue two small black felt dots on the hood as eyes above the teeth. Eyes plus teeth is what makes it a shark face instead of a gray hood with trim.", "Optional pro finish: glue two small black felt dots on the hood as eyes above the teeth. Eyes plus teeth is what makes it a shark face instead of a gray hood with trim."]}, "walking-taco": {"m": ["Tan vest or tan t-shirt, 1 (own: from closet)", "Brown, red, green, and yellow felt sheets, 1 pack (buy: craft store; construction paper works too)", "Fabric glue, 1 bottle (buy: craft store)", "Headband, 1 (buy: dollar store)", "Scissors, 1 pair (own: from home)"], "s": ["Buy the felt pack, fabric glue, and headband.", "Dress the kid in the tan vest or tan t-shirt.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Pin or lay the brown felt strips on the vest first and check the fold placement in a mirror before gluing, since glued felt cannot be repositioned. Glue two curved strips of brown felt down the front of the tan vest to form the shell fold.", "Make the toppings: cut wavy strips of green felt for lettuce and red circles for tomatoes. Cut yellow rectangles for cheese and brown blobs for beef. Glue them in a row across the chest and shoulders so they spill out like a taco filling.", "Make the headband garnish: glue one green felt strip and one red felt circle to the headband. Wear it with the vest as a lettuce and tomato topper.", "Optional pro finish: glue a fringe of thin yellow felt strips along the bottom edge of the vest so cheese spills out all around.", "Optional pro finish: glue a fringe of thin yellow felt strips along the bottom edge of the vest so cheese spills out all around."]}, "ramen-bowl": {"m": ["Large cardboard circle, about 2 feet wide (make: cut from a big box)", "White and red acrylic paint, 2 small bottles (buy: craft store)", "Yellow yarn, 1 skein (buy: craft store; yellow string works too)", "White craft foam or 1 foam ball (buy: craft store; white paper works too)", "Chopsticks, 1 pair (own: kitchen drawer)", "Tape and string, 1 roll and about 2 feet (own: household)", "Scissors, 1 pair"], "s": ["Buy the white and red paint, yellow yarn, and white craft foam.", "Test the bowl rim size before cutting: hold the cardboard up and mark where it should sit as a hat. Cut the cardboard circle into a wide bowl rim shape with the scissors, cutting a little larger than you think since you can trim it down but cannot add cardboard back. Paint it white with a red stripe and let it dry fully, about 1 hour.", "Make the noodles: cut dozens of 12-inch yellow yarn strands. Fasten them in a tangled layer across the top of the dry bowl rim with the tape.", "Cut the white craft foam into a half egg shape and paint a yellow yolk dot on it. Let it dry, then tape the egg on top of the noodles and stick the chopsticks in at an angle.", "Wear the bowl rim like a hat with string under the chin, noodles and egg on top. Slurp loudly for effect.", "Optional pro finish: glue two real wooden chopsticks crossed at the top of the noodles, and tape a paper logo circle to the bowl rim so it reads as a branded ramen bowl.", "Optional pro finish: glue two real wooden chopsticks crossed at the top of the noodles, and tape a paper logo circle to the bowl rim so it reads as a branded ramen bowl."]}, "tiny-snail": {"m": ["Neutral beige or tan clothes, 1 set (own: from closet)", "Large cardboard sheet or 1 flattened box (own: from home)", "Brown and tan markers or crayons, 1 set (own: from home)", "Backpack straps, 2, or 2 long ribbons (own: from home)", "Headband, 1 (buy: dollar store)", "Black pom-poms, 2 (buy: craft store; cotton balls work too)", "Tape, 1 roll (own: from home)", "Scissors, 1 pair"], "s": ["Dress the kid in the beige or tan clothes.", "Buy the headband and black pom-poms.", "Safety: cut the cardboard slowly and keep fingers clear of the scissors.", "Draw the oval on the cardboard first and hold it against the kid's back to check the size before cutting, since a too-small shell cannot be fixed. Make the shell: cut the cardboard into a large oval. Draw a spiral from the center outward with the brown marker. Tape the two backpack straps to the back so it wears like a backpack.", "Make the eyestalks: tape two short cardboard strips to the headband so they point up. Tape a black pom-pom to the top of each strip.", "Wear the shell backpack and the headband with the pom-pom eyestalks. Keep the shell light and the straps snug so it rides comfortably.", "Optional pro finish: edge the shell oval with a tan marker border and add a second smaller spiral inside the first for a realistic shell pattern.", "Optional pro finish: edge the shell oval with a tan marker border and add a second smaller spiral inside the first for a realistic shell pattern."]}, "little-witch": {"m": ["Black cape or black bedsheet, 1 (buy: dollar store, or make: cut a cape from a black t-shirt)", "Pointy witch hat, 1 (buy: dollar store)", "Black-and-white striped tights, 1 pair (buy: thrift store or online)", "Green non-toxic face paint, 1 tube (buy: drugstore or craft store)", "Safety pin or ribbon, 1 (own: from the sewing kit)"], "s": ["Buy the pointy witch hat, black-and-white striped tights, and green face paint. Pull a black cape or black bedsheet from the closet.", "Pin the cape at the shoulders with the safety pin or tie it with ribbon.", "Paint the nose, chin, and forehead lightly green with a fingertip or sponge. Use non-toxic kids' green face paint only.", "Pull on the black-and-white striped tights and the pointy witch hat.", "Carry a branch from the yard as a broom if one is handy.", "Optional pro finish: tie the ribbon in a bow at the front of the cape instead of using a safety pin. A bow at the neck reads as costume; a visible safety pin reads as craft project.", "Optional pro finish: tie the ribbon in a bow at the front of the cape instead of using a safety pin. A bow at the neck reads as costume; a visible safety pin reads as craft project."]}, "spider": {"m": ["Black sweatshirt and black sweatpants, 1 set (own: from closet)", "Black socks, 8 (4 pairs, own: from the sock drawer)", "Newspaper or tissue paper, 3 to 4 sheets, for stuffing (own: from home)", "Thin black rope or black yarn, 4 feet (buy: craft store)", "Black fabric glue, 1 bottle, or a needle and black thread (buy: craft store)", "Large googly eyes, 2 (buy: craft store; drawn paper circles work too)", "White face paint, 1 tube (buy: craft store or costume aisle)"], "s": ["Buy the black yarn, black fabric glue or black thread, googly eyes, and white face paint. Lay the black sweatshirt flat.", "Stuff each of the 8 socks about half full with crumpled newspaper or tissue. Leave the top half empty so each leg can bend.", "Pin the stuffed socks in place on the sweatshirt first and check the spacing in a mirror before committing. Then use the black fabric glue or a few stitches to attach 4 stuffed socks down each side of the sweatshirt, spaced so they stick out like legs, since glued legs cannot be moved.", "Poke the black yarn through the middle of each stuffed sock and tie it for a knee bend. Glue one googly eye on each shoulder of the sweatshirt. Dress in the black sweatshirt and black sweatpants, then put on the leg-covered sweatshirt.", "Safety: use non-toxic face paint, and keep the googly eyes on the shoulders, not near the face.", "Dot the white face paint around the eyes as spider markings.", "Optional pro finish: run one long strand of black yarn across the back of the sweatshirt like a web anchor line, and add small white face-paint dots down the outside of each leg.", "Optional pro finish: run one long strand of black yarn across the back of the sweatshirt like a web anchor line, and add small white face-paint dots down the outside of each leg."]}, "backyard-hero": {"m": ["Old pillowcase or t-shirt for the cape, 1 (make: cut up)", "Solid-color t-shirt to wear, 1 (own)", "Cardstock or foam letter for the first initial, 1 sheet (make: cut from cardstock, or buy: craft store)", "Ribbon or string for cape ties, about 2 feet (own, or buy: craft store)", "Safety pins, 2", "Scissors, 1 pair"], "s": ["Measure first: hold the pillowcase against the back and mark waist length before cutting. Cut the cape with the scissors, a cape cut too short cannot be lengthened, so leave it long and trim after the first fitting.", "Cut the first initial from the cardstock with the scissors. Pin it to the chest of the solid-color t-shirt with a safety pin.", "Safety: keep the neck bow loose and easy to pull free. Never tie anything tight around the neck.", "Thread the ribbon through the top corners of the cape. Tie it at the front of the neck in a loose quick-release bow. Trim the ribbon ends with the scissors.", "Optional pro finish: outline the felt initial with a fabric marker in a contrasting color. The outline makes the emblem readable from across the yard.", "Optional pro finish: outline the felt initial with a fabric marker in a contrasting color. The outline makes the emblem readable from across the yard."]}, "pickle": {"m": ["Green tunic or oversized green t-shirt, 1 (buy: thrift store, or own: from closet)", "Green bubble wrap or green pom-poms, about 20 bumps (buy: craft store, or make: twist bits of green fabric)", "Fabric glue, 1 tube (buy: craft store)", "Green non-toxic face paint, 1 tube (buy: drugstore)"], "s": ["Lay out all the bumps on the tunic DRY first and step back to check the pattern is even, once fabric glue sets, bumps cannot be moved. Space them in a loose grid so no bare patches show. Buy the green tunic, green bubble wrap, and green face paint, then glue the bumps all over the front and back of the green tunic for the bumpy pickle texture.", "Let the fabric glue dry flat for 30 minutes.", "Paint the face with the green face paint, then draw on a smug grin with one raised eyebrow.", "Wear the green tunic over regular clothes and stand tall.", "Optional pro finish: add a slightly darker green felt band at the top and bottom of the tunic. The bands frame the bumps and make it read as a whole pickle instead of a bumpy shirt.", "Optional pro finish: add a slightly darker green felt band at the top and bottom of the tunic. The bands frame the bumps and make it read as a whole pickle instead of a bumpy shirt."]}, "vampire": {"m": ["Black cape or black bedsheet, 1 (buy cape: costume aisle; or make: from a black sheet from home)", "Black shirt and pants, 1 set (own: from closet)", "Plastic vampire fangs, 1 pair (buy: costume aisle or dollar store)", "Hair gel or pomade, 1 (own: from home)", "Red lipstick or red face paint, 1 (buy: pharmacy or costume aisle)", "White face powder or pale face paint, 1 (buy: costume aisle)"], "s": ["Buy the black cape, vampire fangs, pale face paint, and red lipstick if needed.", "Dress in the black shirt and pants.", "Make the hair: work the hair gel through the hair with your fingers. Press it straight back until it sits flat and slick.", "Safety: use non-toxic costume makeup, and skip the vampire fangs for small kids who might choke on them.", "Make the face: dust the pale face paint over the face and neck. Dab a thin line of red lipstick at each corner of the mouth like drips of blood.", "Wear the black cape over the shoulders and pop the vampire fangs in last before photos.", "Optional pro finish: paint the nails black and pop the cape collar up high, since the collar silhouette is what reads as vampire from across the room.", "Optional pro finish: paint the nails black and pop the cape collar up high, since the collar silhouette is what reads as vampire from across the room."]}, "bamboo-demon": {"m": ["Pink bathrobe or kimono-style robe, 1 (own, or buy: clothing store)", "Long dark wig, 1 (buy: toy store or online)", "1 cardboard tube from wrapping paper or paper towels (make: save from home)", "Ribbon or string, about 3 feet (own, or buy: craft store)", "Red non-toxic face paint, 1 tube (buy: toy store)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the long dark wig, ribbon, and red non-toxic face paint.", "Measure the tube against the face first and mark chin width. Cut the cardboard tube slightly LONG with the scissors, you can trim it down, but a tube cut too short cannot be fixed. Tape a length of ribbon to each end of the tube.", "Safety: keep the knot loose enough to talk and breathe easily. Never tie anything tight around the head or neck.", "Tie the cardboard tube across the mouth with the ribbon, knotting loosely at the back of the head.", "Pull on the pink bathrobe. Put on the long dark wig.", "Dab a small red mouth mark on the cardboard tube with the red non-toxic face paint.", "Optional pro finish: draw bamboo segment lines along the tube with a brown marker. Three quick lines turn a cardboard tube into a bamboo muzzle.", "Optional pro finish: draw bamboo segment lines along the tube with a brown marker. Three quick lines turn a cardboard tube into a bamboo muzzle."]}, "emoji-crew": {"m": ["1 yellow t-shirt per person (buy: craft store, or use one you own)", "1 large white paper plate, 10-inch, or cardboard circle per person (make: use what you own)", "Markers in black, red, and blue, 1 set (make: use what you own)", "Scissors, 1 pair and tape, 1 roll"], "s": ["Buy yellow t-shirts if the crew does not own them.", "Safety: adults handle the scissors when cutting the paper plates or cardboard circles.", "Draw the emoji on the paper plate first in pencil, then go over it with the markers. Trim the plate or cardboard circle only where it overhangs the design. Cut small: a plate trimmed too far looks like a scrap.", "Tape the paper plate to the chest of the yellow t-shirt, centered like a face.", "Gather the crew in a row for photos, keeping the paper plates taped flat so they do not swing.", "Optional pro finish: outline the whole plate edge in black marker. The outline makes the face pop from across the room.", "Optional pro finish: outline the whole plate edge in black marker. The outline makes the face pop from across the room."]}, "robot-crew": {"m": ["Medium cardboard box per person, 1 each (make: from home or moving boxes)", "Small cardboard box per person for the head, 1 each (make: from cereal or shoe boxes)", "Aluminum foil, 1 large roll (buy: grocery store)", "Plastic bottle caps, about 20 total (own)", "Duct tape, 1 roll (buy: hardware store)", "Black permanent marker, 1 (own)", "Elastic string or yarn, 6 feet (buy: craft store)", "Glow sticks, 1 per person (buy: dollar store)"], "s": ["Buy the aluminum foil, duct tape, glow sticks, and elastic string.", "Cut the eye holes BIG. You can cover extra space with foil, but you cannot add cardboard back. Cut the boxes slowly and keep fingers clear of the scissors.", "Cut head and arm holes in each medium cardboard box so they slide over the torso. Cut eye holes in the small cardboard boxes for heads.", "Wrap every box in aluminum foil, taping the foil down with duct tape. Draw dials and gauges on the chest with the black permanent marker. Tape the plastic bottle caps next to the dials as buttons.", "Wrap leftover aluminum foil around each arm from wrist to shoulder and tape the ends with duct tape. Or cut the armholes in the torso box big enough to slide bare arms through.", "Each person slides into a torso box and holds or ties the small cardboard box on their head. Tie the elastic string under the chin to keep the head box on. Crack a glow stick and tape it to the chest as a power light.", "Optional pro finish: give each robot a name badge ('UNIT 7', 'BEEP BOOP'). Named robots get talked to; unnamed robots get looked at. The badge is the personality.", "Optional pro finish: give each robot a name badge ('UNIT 7', 'BEEP BOOP'). Named robots get talked to; unnamed robots get looked at. The badge is the personality."]}, "cereal-crew": {"m": ["Solid-color shirt and pants per person, 1 set each (own)", "Empty cereal boxes, 1 per person (make: save from home)", "Markers or crayons in assorted colors, 1 pack (own)", "String, about 4 feet per person (own)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Each person invents a cereal name.", "Open the box along the side seam and flatten it BEFORE cutting, a flat box cuts cleanly, a 3D box wobbles. Cut the front panel off an empty cereal box with the scissors, keeping the panel as large as possible.", "Decorate the panel with the markers or crayons. Draw a mascot, add a prize burst, and write the cereal name in big letters.", "Tape string to the top corners of each panel with the tape.", "Wear the panel over the solid-color shirt like a sandwich board.", "Optional pro finish: add a 'prize inside' burst and a fake nutrition joke ('100% daily value of fun') in the corner. Real cereal boxes have fine print; yours should too.", "Optional pro finish: add a 'prize inside' burst and a fake nutrition joke ('100% daily value of fun') in the corner. Real cereal boxes have fine print; yours should too."]}, "decades-crew": {"m": ["Each person's own closet clothes (make: use what you own)", "1 printed decade card per person, e.g. 70s, 80s, 90s, cardstock or paper (make: hand-letter on paper)", "Scissors, 1 pair", "Tape, 1 roll or safety pins, 1 pack", "Hair gel or spray, 1 (buy: drugstore)"], "s": ["Everyone digs through their closet clothes and picks a different decade.", "Safety: adults handle the scissors when trimming the decade cards.", "Letter the decade card BIG, 4-inch letters minimum, because the card is the costume's label. Hand-letter a decade card on paper, like '80s, and tape it to each chest. A small card nobody can read defeats the purpose.", "Build each look with closet props only: bell-bottoms and a headband for the 70s. Neon and high socks for the 80s. Flannel tied at the waist for the 90s.", "Style hair with hair gel to sell the decade: a big part for the 70s. A scrunchie side-ponytail for the 80s.", "Keep props light so the looks survive a whole night of walking.", "Optional pro finish: give each decade one era-perfect prop, an inflatable microphone for the 80s, a fake vinyl record for the 70s. One prop per person keeps it cheap and specific.", "Optional pro finish: give each decade one era-perfect prop, an inflatable microphone for the 80s, a fake vinyl record for the 70s. One prop per person keeps it cheap and specific."]}, "under-the-sea": {"m": ["Jellyfish: 1 clear umbrella (buy: dollar store)", "Jellyfish: pastel ribbons, 1 spool (buy: craft store; crepe paper strips work too)", "Crab: red shirt and pants, 1 set, plus red mittens or red socks, 1 pair, for hands (own: from closet)", "Fish: silver or blue clothes, 1 set, and 1 large cardboard fish cutout (own: from home)", "Seaweed: green clothes, 1 set, and long green streamers, 1 pack (buy: party store)", "Waves: blue sheet or blue blanket, 1 (own: from home)", "Tape, 1 roll, and scissors, 1 pair (own: from home)"], "s": ["Assign one sea creature per person. Buy the clear umbrella, pastel ribbons, and green streamers. Pull the colored clothes from closets.", "Safety: cut the ribbons slowly and keep fingers clear of the scissors. Hold the clear umbrella high and keep the tentacle ribbons clear of faces.", "Cut one ribbon first and tape it to the umbrella edge to test the drape before cutting the rest. Jellyfish: cut the pastel ribbons into 3-foot lengths. Tape them to the edge of the clear umbrella so they dangle like tentacles. Hold the clear umbrella overhead.", "Crab: dress in red and slide the red mittens or red socks onto the hands. Hold both hands up with fingers pinched like claws. Fish: tape the cardboard fish cutout to the chest over the silver clothes.", "Seaweed: tape the green streamers to the shoulders and arms so they wave when the arms move. Everyone together can hold the blue sheet behind the group as a wave backdrop for the photo.", "Optional pro finish: tape small silver star stickers to the ribbons as bubbles, and give the fish a paper gill slit detail with marker.", "Optional pro finish: tape small silver star stickers to the ribbons as bubbles, and give the fish a paper gill slit detail with marker."]}, "dino-rangers": {"m": ["Khaki shirt, 1, and khaki pants, 1 pair, per grown-up (make: use what you own)", "Green hoodie per child, 1 each (buy: thrift store, or use one you own)", "White paper or card, 2 sheets (make: use what you own)", "1 toy dinosaur or plush per kid (buy: toy store)", "Ribbon or string, 18 inches per kid (make: use what you own)", "Tape, 1 roll and scissors, 1 pair"], "s": ["Dress the grown-ups in the khaki shirt and pants, and roll the sleeves for the field-guide look.", "Buy or dig out the green hoodie for each kid, the toy dinosaur, and the ribbon.", "Safety: adults handle the scissors when cutting the white paper.", "Draw the eye spots on paper first and hold them against the hood to check the placement. Cut two oval eye spots from the white paper with the scissors, about 3 inches tall. Cut them smaller than you think: oversized eyes slide off the hood sides.", "Safety: skip small plastic dinosaur toys for kids under three, since they are a choking hazard.", "Loop the ribbon around the toy dinosaur like a leash, and tie the other end to the kid's wrist. Keep the leash short so the toy dinosaur does not drag.", "Optional pro finish: write each kid's dinosaur name on masking tape and stick it on the khaki shirt like a field badge. Ranger plus name tag sells the explorer story.", "Optional pro finish: write each kid's dinosaur name on masking tape and stick it on the khaki shirt like a field badge. Ranger plus name tag sells the explorer story."]}, "board-game-pieces": {"m": ["Black or white monochrome clothes, 1 set per person (own)", "Large cardboard boxes, 2 to 3 (make: collect spares)", "White and black acrylic paint, 1 small bottle each (buy: craft store, tempera paint works too)", "Paintbrushes, 1 wide and 1 detail", "Black marker, 1 (buy: dollar store)", "Ribbon or string for straps, about 4 feet per board (own)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Each person picks a game piece to be.", "Sketch each piece on the cardboard with marker BEFORE cutting. Cut a cube shape from a large cardboard box for the die with the scissors, measure the head first and cut the opening small, widening as needed. Cut flat boards from another box for the playing card and the domino.", "Paint the die and card white and the domino black with the acrylic paint and paintbrushes. Let the paint dry fully.", "Add dots and card symbols with the black marker and the white acrylic paint once the base coats are dry.", "Safety: cut the die box eye holes generously so you can see clearly. Only wear the die box once all paint is fully dry.", "Tape ribbon straps to the flat boards so they hang front and back over the black or white monochrome clothes. Wear the die box over the head with the eye holes lined up.", "Optional pro finish: paint a thin gold border around the card and domino edges. The border is what makes them read as game pieces instead of painted cardboard.", "Optional pro finish: paint a thin gold border around the card and domino edges. The border is what makes them read as game pieces instead of painted cardboard."]}, "rain-cloud-rainbow": {"m": ["Gray t-shirt or sweatshirt, 1 (buy: thrift store, or own: from closet)", "White cotton balls or polyester stuffing, 1 bag (buy: dollar store or craft store)", "Blue paper raindrops, about 15 (own: cut from blue construction paper)", "String, 1 spool, and tape, 1 roll (own: household tools)", "Fabric glue, 1 tube (buy: craft store)", "Rainbow-striped shirt, 1, or a white shirt, 1, plus rainbow fabric markers, 1 set (buy: thrift store or craft store)", "Blue non-toxic face paint for one rain streak, 1 tube (buy: drugstore, optional)"], "s": ["Buy the gray t-shirt, white cotton balls, fabric glue, and rainbow-striped shirt or rainbow fabric markers.", "Arrange the cotton balls on the shirt DRY first and step back to check the cloud coverage, once fabric glue sets, cotton balls cannot be moved. Plan for full coverage with no gray showing through the middle. Then glue the cotton balls in clumps across the gray t-shirt to make clouds.", "Fix the blue paper raindrops to short pieces of string with tape. Hang the strings from the bottom edge of the gray t-shirt so they dangle.", "The rainbow person: wear the rainbow-striped shirt, or draw rainbow arcs across a white shirt with the rainbow fabric markers.", "Stand side by side: the cloud holds arms out wide. The rainbow stands just behind, peeking out after the 'storm'. Add one blue rain streak on a cheek with the blue face paint if you like.", "Optional pro finish: hang the raindrops at staggered lengths, not all even. Uneven drops look like real rain; a straight row looks like a mobile.", "Optional pro finish: hang the raindrops at staggered lengths, not all even. Uneven drops look like real rain; a straight row looks like a mobile."]}, "doctor-bride": {"m": ["1 old dark suit or jacket (make: use what you own)", "Green face paint, non-toxic, 1 tube (buy: drugstore)", "2 plastic neck bolts, costume style (buy: craft store; foil-covered cardboard tubes work too)", "1 white dress or old white sheet (make: use what you own)", "White hair spray, 1 can (buy: drugstore)", "Tape, 1 roll or glue, 1 bottle", "Scissors, 1 pair", "Dark eye shadow, 1 (make: use what you own)"], "s": ["Buy the green face paint, plastic bolts, and white hair spray.", "Safety: keep face paint away from the eyes, and patch-test it first on sensitive skin. Wash it off the same night.", "The Doctor: paint the face and neck green with the green face paint.", "Tape the two plastic bolts to the sides of the neck, and wear the dark suit with the collar up.", "Put the white dress or sheet on first and mark the tear line with tape: knee length for walking, longer for photos. Tear the bottom hem into strips with your hands, starting with small tears you can widen. Torn fabric cannot be untorn, so start shorter than you want.", "Smudge dark eye shadow under the eyes.", "Optional pro finish: smudge a little green face paint onto the bride's neck and hands too. The green spreading to the bride ties the two halves of the costume together.", "Optional pro finish: smudge a little green face paint onto the bride's neck and hands too. The green spreading to the bride ties the two halves of the costume together."]}, "breakfast-buffet": {"m": ["Cardboard sheets, 1 per person about 2x2 feet (make: cut from boxes)", "Markers in assorted colors, 1 pack (own, or buy: dollar store)", "String or yarn, about 4 feet per person (own)", "Scissors, 1 pair"], "s": ["Each person picks a breakfast item.", "Draw the food on paper FIRST to plan the layout, then cut a large circle or rectangle from the cardboard sheets with the scissors. Draw big, the food must read from across the room, so fill the whole board.", "Draw the food big on the cardboard with the markers. Draw a fried egg, bacon strips, buttered toast, a pancake stack, a glass of OJ, or a coffee mug.", "Safety: an adult pokes the holes in the top corners with the tip of the scissors, since pushing through cardboard takes force.", "Thread the string through the holes and wear the sign over normal clothes like a sandwich board.", "Optional pro finish: make one extra small sign that says 'BREAKFAST BUFFET, all you can eat' and have the tallest person carry it. The sign turns five food boards into one group costume.", "Optional pro finish: make one extra small sign that says 'BREAKFAST BUFFET, all you can eat' and have the tallest person carry it. The sign turns five food boards into one group costume."]}, "ghost-hunters": {"m": ["1 khaki or tan jumpsuit, or matching shirt and pants, per person (buy: thrift store)", "1 small cardboard box per person, shoebox size (make: use what you own)", "White paper, 2 sheets, and markers for name patches (make: use what you own)", "1 sheet black cardboard per person (make: from a box)", "Packing tape or glue, scissors"], "s": ["Buy the khaki jumpsuit or matching shirt and pants for each person.", "Tape the small cardboard box shut for the backpack.", "Safety: adults handle the scissors when cutting the black cardboard.", "Draw the straps, dial, and hose shapes on the black cardboard with marker first and hold them against the box to check the size. Cut them with the scissors. Cut the hose shape last and widest: it is the most visible piece.", "Mark each last name on the white paper with the markers. Tape it to the chest as a name patch.", "Wear the backpack over the jumpsuit, and keep the box small and light so kids can wear it all night.", "Optional pro finish: write each person's last name on the white paper patch in block letters and tape it to the chest. The name patch is the detail that turns khaki clothes into a uniform.", "Optional pro finish: write each person's last name on the white paper patch in block letters and tape it to the chest. The name patch is the detail that turns khaki clothes into a uniform."]}, "haunted-animatronics": {"m": ["1 large cardboard box per person, big enough to cover the head (make: use what you own)", "2 red LED tea lights per person (buy: dollar store)", "Paint in gray, black, and one accent color, 1 small bottle each (buy: craft store)", "1 set old clothes with holes or tears (make: use what you own)", "Hot glue gun, 1; scissors, 1 pair; utility knife, 1 (adults only)"], "s": ["Buy the red LED tea lights and the paint. Pull the old clothes with holes and the large cardboard boxes from home.", "Safety: an adult handles the utility knife and the hot glue for every cut and glue step.", "Mark the eye holes and the wide jagged mouth on the OUTSIDE of the box first, then have the wearer hold the box up to check the eye placement before any cutting. Cut with the utility knife, adults only, cutting the eye holes generous and the mouth wide. Cardboard cut away cannot be put back, and small eye holes make a blind hazard.", "Paint the box gray with black scuffs and cracks. Glue one red LED tea light inside each eye hole.", "Safety: make the eye holes large, and never wear the box near stairs or traffic, since side vision is limited.", "Wear the box over the head with the eyes lined up to the holes. Wear the old clothes with holes underneath, and move in short jerky steps, freezing between moves.", "Optional pro finish: paint black scuffs and cracks around the eye holes before adding the lights. The damage detail is what reads as haunted instead of just boxy.", "Optional pro finish: paint black scuffs and cracks around the eye holes before adding the lights. The damage detail is what reads as haunted instead of just boxy."]}, "mystery-crew": {"m": ["Orange, purple, blue, and red t-shirts, 1 each (buy: thrift store, or own: from closet)", "Dog ears headband or a brown dog costume piece, 1 (buy: dollar store)", "Fake magnifying glass, 1 (buy: dollar store, or make: a paper circle taped to a stick)", "Headband or scarf in a matching color, 1 per person (own: from the drawer)", "Brown non-toxic face paint for the dog's nose, 1 tube (buy: drugstore)"], "s": ["Buy the dog ears headband and the fake magnifying glass.", "Assign roles: orange leader, purple style icon, blue brains, red goofball, and the dog wears the ears.", "Each person: put on their color's t-shirt and tie a matching headband or scarf.", "The brains carries the fake magnifying glass. Paint a brown nose on the dog with the brown face paint.", "Group the four humans in a line with the dog in front. All point at something suspicious for the classic pose.", "Optional pro finish: write each person's role on a small paper name tag ('the brains', 'the leader'). The tags turn colored shirts into characters for anyone who does not know the reference.", "Optional pro finish: write each person's role on a small paper name tag ('the brains', 'the leader'). The tags turn colored shirts into characters for anyone who does not know the reference."]}, "headless-horsemen": {"m": ["Black cape or black sheet, 1 per person (buy: dollar store, or own: black sheet)", "Small jack-o-lantern bucket or foam pumpkin, 1 per person (buy: dollar store)", "Broom or stick-horse substitute, 1 per person (own: broom from home)", "Tape, 1 roll (own)", "Glow bracelets, 1 pack (buy: dollar store)"], "s": ["Buy the black cape, the jack-o-lantern bucket, and the glow bracelets.", "Drape the black cape or black sheet over the shoulders.", "Safety: keep your real head tucked low so you can see the ground.", "Tuck the chin into the chest, and hold the jack-o-lantern bucket up at shoulder height like a carried head.", "Add a glow bracelet to each wrist so drivers can see you in the dark.", "Hold the broom between the legs like a horse, and gallop in a group line.", "Optional pro finish: put a battery tea light inside each jack-o-lantern bucket. A glowing 'head' reads from a block away and keeps the group visible.", "Optional pro finish: put a battery tea light inside each jack-o-lantern bucket. A glowing 'head' reads from a block away and keeps the group visible."]}, "haunted-portraits": {"m": ["1 set old-fashioned dark clothes per person, e.g. a vest, long skirt, or button-up (make: use your closet)", "Gray and white face paint, non-toxic, 1 set (buy: drugstore)", "1 large picture frame or cardboard frame per person (buy: thrift store for the frame, or make from cardboard)", "Hair spray or powder for a grayed look, 1 (buy: drugstore)"], "s": ["Buy the gray and white face paint and the hair powder.", "Paint each face pale gray with white highlights on the cheekbones and nose, using the gray and white face paint.", "Gray the hair with the hair powder.", "Dress in the old-fashioned dark clothes from the closet.", "Hold the picture frame or cardboard frame up around the face like a living portrait.", "Pose together in a row of frames for group photos, keeping the face paint light around the eyes.", "Optional pro finish: dust the hair with the gray powder and add white highlights on the cheekbones and nose. The highlights are what read as painted portrait instead of just pale.", "Optional pro finish: dust the hair with the gray powder and add white highlights on the cheekbones and nose. The highlights are what read as painted portrait instead of just pale."]}, "goggle-crew": {"m": ["1 yellow t-shirt per person (buy: craft store, or use one you own)", "1 pair denim overalls per person (buy: thrift store, or use one you own)", "1 pair swim or safety goggles per person (buy: toy store)", "1 pair black gloves per person (buy: dollar store)"], "s": ["Buy the yellow t-shirts, denim overalls, goggles, and black gloves.", "Each person puts on the yellow t-shirt, the denim overalls, and the black gloves.", "Push the goggles up on the forehead like safety gear, not over the eyes, so everyone can see.", "Walk in a pack and greet people in gibberish for the full effect.", "Skip any real tools or hard hats so the look stays clearly costume, not work gear.", "Optional pro finish: push the goggles up on the forehead, never over the eyes. Forehead goggles are the character's signature; over the eyes you just look like a swimmer.", "Optional pro finish: push the goggles up on the forehead, never over the eyes. Forehead goggles are the character's signature; over the eyes you just look like a swimmer."]}, "garden-gnome": {"m": ["Earth-tone shirt and pants, 1 set (own)", "Cardboard for the hat, 1 sheet (make: from a box)", "Blue paint for the hat, 1 small bottle (buy: craft store)", "White face paint for the beard, non-toxic, 1 tube (buy: drugstore)", "Toy fishing rod or small garden shovel, 1 (buy: dollar store)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the blue paint, the white face paint, and the toy fishing rod.", "Safety: adults handle the scissors when cutting the cardboard.", "Cut the sheet cardboard to size, roll it into a tall cone, and tape it shut.", "Paint the cone with the blue paint for the hat, and let it dry.", "Test the face paint on the inside of the wrist first and wait 10 minutes, kids' skin reacts more than you expect. Use the brown and black non-toxic face paint to draw a round nose and rosy cheeks. Keep all paint clear of the eyes and mouth.", "Wear the cone hat with the earth-tone shirt and pants, and carry the toy fishing rod.", "Optional pro finish: carry a tiny watering can or a foam mushroom. Gnomes have props, the hat and beard say gnome, the watering can says garden gnome.", "Optional pro finish: carry a tiny watering can or a foam mushroom. Gnomes have props, the hat and beard say gnome, the watering can says garden gnome."]}, "black-cat": {"m": ["Black shirt and pants or sweatsuit, 1 set (own)", "Plain headband, 1 (buy: dollar store)", "1 sheet black craft felt, 9x12 inches (buy: craft store, construction paper works too)", "Black construction paper, 1 sheet (make: cut a mask from it)", "Black non-toxic face paint, 1 tube (buy: toy store)", "Small drawstring bag or pillowcase, 1 (own)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the plain headband, black craft felt, and black non-toxic face paint.", "Cut two triangle ears from the black craft felt with the scissors, about 4 inches tall. Cut one eye mask shape from the black construction paper.", "Tape the ears upright to the plain headband.", "Safety: cut the eye holes wide in the mask so vision stays clear.", "Tape the mask on with long tape tabs at the temples. Or draw whiskers with the black non-toxic face paint.", "Pull on the black shirt and pants and put on the plain headband. Carry the small drawstring bag over one shoulder.", "Optional pro finish: tape three pipe cleaners to each cheek as whiskers instead of drawing them. Real whiskers catch the light and photograph ten times better.", "Optional pro finish: tape three pipe cleaners to each cheek as whiskers instead of drawing them. Real whiskers catch the light and photograph ten times better."]}, "block-monster": {"m": ["Solid-color sweatsuit, any color, 1 set (own)", "1 large cardboard box (make: cut it into square blocks)", "Packing tape, 1 roll", "Scissors, 1 pair", "Non-toxic face paint, 1 tube (buy: toy store)"], "s": ["Cut the large cardboard box into square blocks with the scissors: two large (shoulder size), four medium (forearm and shin size). Test-hold each block against the body BEFORE taping, blocks taped in the wrong spot look lopsided all night.", "Tape one large block to each shoulder with the packing tape.", "Tape one medium block to each forearm and shin with the packing tape.", "Pull on the solid-color sweatsuit under the blocks.", "Safety: keep the face paint clear of the eyes.", "Draw a blocky square-toothed grin on the face with the non-toxic face paint.", "Optional pro finish: edge every block with silver duct tape. The metallic edge catches light and makes cardboard read as robot armor.", "Optional pro finish: edge every block with silver duct tape. The metallic edge catches light and makes cardboard read as robot armor."]}, "space-crewmate": {"m": ["Plain sweatsuit in one solid color, red recommended, 1 set (own: from closet)", "Cardboard, 1 sheet about 12x16 inches (own: from a box flap)", "Aluminum foil, about 2 feet (own: from the kitchen)", "Backpack straps, 2, or 2 long shoelaces (own: from home)", "Markers, 3 to 4 colors (own: from home)", "Tape, 1 roll (own: from home)", "Scissors, 1 pair"], "s": ["Dress in the solid-color sweatsuit.", "If you have more than one person, give each a different color.", "Wrap the cardboard in aluminum foil for the backpack. Draw vents, dials, and one big red button with the markers. Tape the two backpack straps to the back of the cardboard.", "Wear the foil backpack with the straps over your shoulders. Tape the bottom corners snug to the sweatsuit so it does not swing.", "Finishing touch: hold one finger to your lips and say sus for the photo.", "Optional pro finish: draw a crewmate ID badge on an index card (name, color, and CREW) and tape it to the chest.", "Optional pro finish: draw a crewmate ID badge on an index card (name, color, and CREW) and tape it to the chest."]}, "sun-moon": {"m": ["Yellow shirt and pants for the Sun, 1 set (own: from closet)", "Navy or black shirt and pants for the Moon, 1 set (own: from closet)", "Yellow cardstock, 2 sheets (buy: craft store; construction paper works too)", "Silver star stickers, 1 sheet (buy: craft store; cut paper stars work too)", "White and yellow paper, 1 sheet each, for the crescent (own: from home)", "Tape, 1 roll, and scissors, 1 pair (own: from home)"], "s": ["One person dresses head to toe in yellow, the other in navy or black.", "Buy the yellow cardstock and the silver star stickers.", "Safety: cut the cardstock slowly and keep fingers clear of the scissors.", "Cut one ray first and tape it to the neckline to test the length before cutting the other nine, since cardstock cannot be lengthened. Make the sun rays: cut 10 long triangles from the yellow cardstock, then tape them around the neckline and sleeves of the yellow shirt so they point outward.", "Cut a large crescent from the white paper and tape it to the chest of the navy shirt. Scatter the silver star stickers across the shirt and arms.", "Finishing touch: the Sun spreads arms wide to show the rays while the Moon holds one hand near the crescent.", "Optional pro finish: glue the rays in pairs back to back so they are stiff and yellow on both sides, and edge the crescent with silver marker.", "Optional pro finish: glue the rays in pairs back to back so they are stiff and yellow on both sides, and edge the crescent with silver marker."]}, "moth-porch-light": {"m": ["Neutral shirt and pants in gray, brown, or tan, 1 set (own: from closet)", "Large cardboard box, 1 (own: cut two wing shapes from it)", "Brown and tan markers or paint, 1 set (buy: craft store)", "Brown craft pipe cleaners, 2 (buy: craft store; brown yarn works too)", "Headband, 1 (own: from the drawer)", "Yellow t-shirt and yellow pants, 1 set (buy: thrift store, or own: from closet)", "Cone lampshade, 1 (buy: thrift store)", "Tape, 1 roll, and scissors, 1 pair (own: household tools)"], "s": ["Draw both wing ovals on the box first and have the moth hold their arms out to check the span, wings cut too small look like shoulder pads, and cardboard cut away cannot be put back. Cut two large oval wing shapes from the large cardboard box with the scissors. Buy the brown craft pipe cleaners, brown and tan markers, and cone lampshade.", "Draw eye spots and scalloped edges on the wings with the brown markers. Tape one wing to each arm of the neutral shirt and pants.", "Bend the brown craft pipe cleaners into feathery antennae and tape them to the headband for the moth.", "Put on the yellow t-shirt and yellow pants. Pop the cone lampshade over the head like a lampshade hat.", "Stand next to the moth with arms out, buzzing.", "Optional pro finish: curl the wing tips slightly forward and tape them so they cup inward. Real moth wings curve; flat cardboard reads as a sign.", "Optional pro finish: curl the wing tips slightly forward and tape them so they cup inward. Real moth wings curve; flat cardboard reads as a sign."]}, "raptor-ranger": {"m": ["Khaki shirt and hat for the ranger, 1 set (own: from closet, or buy at a thrift store)", "Green hoodie or green t-shirt for the raptor, 1 (own: from closet)", "Green felt sheet, 9x12 inches, 1 (buy: craft store; construction paper works too)", "Rope, 3 feet, or 1 toy dog leash (buy: pet aisle)", "Face paint, green and black, 1 set (buy: costume aisle or craft store)", "Scissors, 1 pair, and tape, 1 roll (own: household)"], "s": ["Decide who is the ranger and who is the raptor, then lay out both outfits. Buy the 3 ft rope or toy dog leash and the face paint if you do not have them.", "Safety: cut the green felt sheet slowly and keep fingers clear of the scissors.", "Draw the tail shape on the felt first and hold it up to the raptor's back to check the length before cutting, since a too-short tail cannot be lengthened. Then cut one long triangle from the green felt sheet for the tail. Tape it to the back of the raptor's green shirt so it hangs behind them.", "The ranger wears the khaki shirt and hat with the toy dog leash in hand. The raptor wears the green shirt with the tail attached.", "Safety: use non-toxic kids face paint, and skip any mask so the raptor can see clearly.", "Paint the raptor's snout: use the green face paint to draw a snout and two black dots for nostrils. Then the ranger holds the toy dog leash out toward the raptor for photos.", "Optional pro finish: tie the rope as a belt around the ranger's waist and clip a toy walkie-talkie to it for the field-guide look.", "Optional pro finish: tie the rope as a belt around the ranger's waist and clip a toy walkie-talkie to it for the field-guide look."]}, "cat-mouse": {"m": ["2 headbands (buy: dollar store)", "1 sheet black craft felt, 9x12 inches (buy: craft store, construction paper works too)", "1 sheet gray craft felt, 9x12 inches (buy: craft store, construction paper works too)", "Black eyeliner pencil or non-toxic face paint, 1 (buy: toy store)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the headbands, black craft felt, gray craft felt, and black eyeliner pencil.", "Cut one paper ear template first, triangles for the cat, rounds for the mouse, and check both against the headbands. Cut two triangle ears from the black craft felt with the scissors.", "Cut two round ears from the gray craft felt with the scissors, about 3 inches across.", "Safety: keep the eyeliner clear of the eyes.", "Put on the headbands and draw whiskers on both faces with the black eyeliner pencil.", "Optional pro finish: glue a pink felt triangle inside each ear. Inner ears are the five-second detail that makes both animals read instantly.", "Optional pro finish: glue a pink felt triangle inside each ear. Inner ears are the five-second detail that makes both animals read instantly."]}, "ketchup-mustard": {"m": ["1 red t-shirt, 1 yellow t-shirt (make: raid the closet)", "Red felt or construction paper, 1 sheet 9x12 inches (buy: craft store, or use paper from home)", "Yellow felt or construction paper, 1 sheet 9x12 inches (buy: craft store, or use paper from home)", "Safety pins, 8 (buy: dollar store, or raid the sewing kit)", "Scissors, 1 pair"], "s": ["Pick who is ketchup (red shirt) and who is mustard (yellow shirt). No wrong answer, but decide before you start cutting, it avoids the only argument this costume can cause.", "Cut a big blob shape from the red paper, about the size of a dinner plate. Round the edges; a neat circle reads as a sticker, a blob reads as a squeeze of ketchup.", "Cut a matching blob from the yellow paper.", "Pin the red blob to the yellow shirt and the yellow blob to the red shirt with 4 safety pins each, pinned from inside. Each person wears the OTHER condiment's color, that is the joke.", "Optional pro finish: write the nutrition facts on the back of each shirt with a marker ('Serving size: 1 awesome couple'). People will turn you around to read it.", "Safety: pin from inside the shirt so no pin backs touch skin, and keep the pins flat, nobody wants a poke during a hug.", "Stand side by side and take the photo. The internet has decided this is a top-10 couples costume; you are now contractually obligated to look delighted."]}, "plumber-duo": {"m": ["Blue overalls, 2 (buy: thrift store)", "Red t-shirt and green t-shirt, 1 each (buy: thrift store, or own: from closet)", "Red cap and green cap, 1 each (buy: dollar store)", "Brown non-toxic face paint for mustaches, 1 tube (buy: drugstore)", "White circle stickers or white paper, 2 about 2 inches across (buy: dollar store)", "Marker, 1 (own: household)"], "s": ["Buy the blue overalls, red cap, green cap, white circle stickers, and brown face paint. Pull the red t-shirt and green t-shirt from the closet.", "Write a big 'M' on one white circle and an 'L' on the other with the marker. Stick or tape them to the front of the red cap and green cap.", "Each brother: wear the blue overalls over their colored t-shirt and cap. Paint on a mustache with the brown face paint. The red brother gets a big bushy one, and the green brother gets a thinner one.", "Roll the overall cuffs once and strike the jump pose with a fist in the air. Talk about fixing pipes all night.", "Optional pro finish: roll the overall cuffs once and scuff the knees with a little brown face paint. Work-worn overalls read as plumbers; crisp new ones read as a uniform costume.", "Optional pro finish: roll the overall cuffs once and scuff the knees with a little brown face paint. Work-worn overalls read as plumbers; crisp new ones read as a uniform costume."]}, "office-couple": {"m": ["White button-down shirts, 2 (own: from closet)", "Name tags, 2 (buy: office supply store, or make: index cards with safety pins)", "Toy teapot or a small real teapot, 1 (own: from the kitchen)", "Black pants or skirts, 2 (own: from closet)", "Marker for writing names, 1 (own: household)"], "s": ["Buy name tags, or make them from index cards and safety pins. Pull the white button-down shirts and black pants or skirts from the closet.", "Write joke job titles on the name tags with the marker and pin them on the white button-down shirts.", "One person carries the toy teapot proudly all evening. The other carries a clipboard or a stack of papers.", "Tuck the white button-down shirts in and straighten each other's collars. Introduce yourselves by your fake titles to everyone you meet.", "Optional pro finish: write the fake titles in a dead-serious font, like 'Regional Teapot Manager'. The comedy is in how official the name tag looks.", "Optional pro finish: write the fake titles in a dead-serious font, like 'Regional Teapot Manager'. The comedy is in how official the name tag looks."]}, "burger-joint-couple": {"m": ["2 white aprons (buy: dollar store or online)", "Fake mustache, 1 (buy: toy store)", "Curly red wig, 1 (buy: toy store or online)", "Costume glasses, 1 pair (buy: toy store)", "Order pad and pencil, 1 set (own, or buy: dollar store)"], "s": ["Buy the white aprons, fake mustache, curly red wig, costume glasses, and order pad.", "Test the mustache position in a mirror BEFORE peeling the adhesive, stick it on dry first, mark the spot lightly, then commit. One partner pulls on a white apron and sticks on the fake mustache with its skin-safe adhesive.", "The other partner pulls on the second white apron, the curly red wig, and the costume glasses.", "Carry the order pad and pencil and take each other's burger orders all night.", "Remove the fake mustache gently at the end of the night.", "Optional pro finish: write 'BURGER JOINT' on both aprons with a red fabric marker, plus a fake name tag each ('Ask me about the secret sauce'). Named staff beats blank aprons.", "Optional pro finish: write 'BURGER JOINT' on both aprons with a red fabric marker, plus a fake name tag each ('Ask me about the secret sauce'). Named staff beats blank aprons."]}, "plug-socket": {"m": ["Cardboard box, 1 large (own: cut two flat panels, one per person)", "Gray and white acrylic paint, 1 small bottle each (buy: craft store)", "Black markers, 1 set (own: household)", "Craft foam, 1 sheet 9x12 inches (buy: craft store; cardboard works too)", "Tape, 1 roll, and string, 1 spool, for wearing (own: household tools)", "Scissors, 1 pair (own: household tools)"], "s": ["Mark the panel size against each wearer BEFORE cutting, a panel cut too small looks like a badge and one cut too big bangs knees, and cardboard cut away cannot be put back. Cut two cardboard panels from the large box with the scissors, each about 2 feet square, one per person, cutting generous and trimming later. Buy the gray and white acrylic paint and the craft foam.", "Make the plug: paint one panel gray. Draw two prongs on the craft foam, cut them out, and tape them sticking up from the top edge.", "Make the socket: paint the other panel white. Draw two dark slots and a round outlet face with the black markers.", "Fix the string to the back corners of each panel with tape so they hang like sandwich boards. The plug person stands next to the socket person.", "Optional pro finish: paint a small lightning bolt between the two panels' meeting edges. The bolt sells the 'about to connect' joke in photos.", "Optional pro finish: paint a small lightning bolt between the two panels' meeting edges. The bolt sells the 'about to connect' joke in photos."]}, "lost-tourist": {"m": ["Button-down shirt, 1 (own, to wrinkle on purpose)", "Sunglasses and camera or phone on a strap, 1 set (own)", "Paper map, 1 (make: print one at home, or draw a fake map on printer paper)", "Luggage tag, 1 (buy: office supply store, or make: index card with string)", "Clear tape, 1 roll (own)"], "s": ["Wrinkle the button-down shirt on purpose. Stuff it in a bag overnight, or ball it up and sit on it for ten minutes.", "Write a fake name and hometown on an index card for the luggage tag. Punch a hole in the card and tie on the string.", "Tape the luggage tag backwards on one shoulder with the clear tape so it faces the wrong way.", "The map is the costume's punchline, fold it wrong-side-out and hold it upside down. A neatly folded map reads as prepared; an upside-down map reads as LOST. Commit to the upside-down.", "Hang the camera or phone around the neck and put the sunglasses on top of the head.", "Walk around looking at the map upside down.", "Optional pro finish: ask strangers for directions to somewhere obvious, in character, all night. The costume is a performance, the map gets you noticed, the bit gets you remembered.", "Optional pro finish: ask strangers for directions to somewhere obvious, in character, all night. The costume is a performance, the map gets you noticed, the bit gets you remembered."]}, "tooth-fairy": {"m": ["Tooth: all-white outfit, 1 set (own: from closet)", "Tooth fairy: white dress or white shirt with a white skirt, 1 (own: from closet)", "White cardstock, 1 large sheet (buy: craft store)", "White felt wings, 1 pair, or 1 wire coat hanger with white pantyhose (buy: craft store, or make: from home)", "Small envelope and play money or a coin, 1 (own: from home)", "Glitter glue, 1 tube (buy: craft store)", "Stick and aluminum foil for the wand, 1 (own: from home)", "Tape, 1 roll, and scissors, 1 pair (own: from home)"], "s": ["Buy the white cardstock, glitter glue, and felt wings if you are not making them.", "Pull the white clothes from the closet.", "Draw the tooth outline lightly in pencil first and hold it against the chest to check the size before cutting. Make the tooth: cut a large tooth shape with two roots from the white cardstock. Edge it with the glitter glue and let it dry. Tape it to the chest of the white outfit.", "Safety: tape down any sharp wire ends from the wire coat hanger, and keep fingers clear of the scissors.", "Make the wings: stretch the white pantyhose over a reshaped wire coat hanger to form two wing loops. Tape the hanger ends to a piece of cardboard worn at the back. Tuck the envelope with play money into a pocket or waistband.", "Tooth fairy: wear the white dress and strap on the wings. Carry the wand made from the stick with an aluminum foil star taped on top.", "Optional pro finish: tuck a tiny card into the envelope that says the tooth exchange rate (one tooth equals one wish) for the full fairy bureaucracy joke.", "Optional pro finish: tuck a tiny card into the envelope that says the tooth exchange rate (one tooth equals one wish) for the full fairy bureaucracy joke."]}, "web-hero-duo": {"m": ["Hero: red and blue sweatsuit, or red shirt with blue pants, 1 set (own: from closet)", "Partner: black jacket and black pants, 1 set (own: from closet)", "Black face paint or black eye mask, 1 (buy: costume aisle)", "White face paint or white stickers, 1 (buy: craft store)", "Red web gloves or red socks for hands, 1 pair (own: from closet)", "Tape, 1 roll (own: from home)"], "s": ["Buy the black face paint or black eye mask, and the white stickers.", "Pull the red and blue outfit and the black jacket and black pants from closets.", "Safety: use non-toxic face paint, and keep paint out of the eyes.", "Test the white web pattern on a paper towel first to check the paint flow, since painted lines cannot be undone on fabric. Hero: paint a black eye mask with the black face paint across the eyes. Add white web lines over the red shirt using the white face paint. Or tear thin strips of tape in a web pattern over the shirt. Pull the red socks onto the hands as web gloves.", "Partner: wear the black jacket and black pants and slick the hair back. Strike the brooding pose. No crafting needed beyond the outfit.", "Finishing touch: the hero throws one arm out in a web-shooting pose while the partner crosses their arms behind them.", "Optional pro finish: run the white tape web pattern across the back of the shirt too, so the costume reads from behind in photos.", "Optional pro finish: run the white tape web pattern across the back of the shirt too, so the costume reads from behind in photos."]}, "plague-doctor": {"m": ["Long black coat or black robe, 1 (buy: thrift store)", "Wide-brim black hat, 1 (buy: dollar store)", "Black half mask or sunglasses, 1 (buy: dollar store)", "Cardboard or craft foam for the beak, 1 sheet 9x12 inches (buy: craft store; stiff paper works too)", "Black gloves, 1 pair (buy: dollar store)", "Hot glue gun, 1 (buy: craft store)", "Black spray paint or black markers, 1 can or set (buy: craft store)"], "s": ["Cut a paper beak template first and hold it against the mask to check the curve and length, a beak cut too long looks silly and one cut too short looks stubby, and neither can be fixed after cutting. Cut a long curved beak shape from the cardboard or craft foam with the scissors. Buy the coat, hat, mask, gloves, hot glue gun, and beak materials.", "Safety: let an adult handle the hot glue gun, and keep fingers away from the nozzle.", "Paint the beak black with the black spray paint and let it dry. Hot-glue the beak to the front of the black half mask so it juts out.", "Safety: fit the black half mask so the eyes are fully open. Never wear a mask that blocks peripheral vision.", "Cut round eye holes in the black half mask and fit it so the eyes are fully open.", "Wear the long black coat, wide-brim black hat, black gloves, and the beaked mask together. Carry a wooden staff or walking stick for the full effect.", "Optional pro finish: paint the finished beak with a second light coat and let it dry fully. One thin coat looks gray in flash photos; two coats read as true black.", "Optional pro finish: paint the finished beak with a second light coat and let it dry fully. One thin coat looks gray in flash photos; two coats read as true black."]}, "crowd-camouflage": {"m": ["Gray hoodie, 1 (own)", "Dark pants, 1 pair (own)", "Gray beanie, 1 (own, or buy: dollar store)", "Blank adhesive name tag, 1 (buy: dollar store)", "Pen, 1 (own)"], "s": ["Pull on the gray hoodie with the hood up, the dark pants, and the gray beanie.", "Leave the blank adhesive name tag blank, that IS the joke. Write nothing on it with the pen and stick it to the chest of the gray hoodie. The one thing that ruins this costume is filling in the tag.", "Keep a blank expression, hood up, and blend into the background of every group photo.", "Optional pro finish: stand in the back row of every group photo with a perfectly blank expression. The costume only works if you commit to being forgettable, ham it up by being boring.", "Optional pro finish: stand in the back row of every group photo with a perfectly blank expression. The costume only works if you commit to being forgettable, ham it up by being boring."]}, "error-404": {"m": ["1 black t-shirt (make: use your closet)", "1 pair black pants (make: use your closet)", "White fabric paint, 1 small bottle, or 1 sheet white paper (buy: craft store)", "1 old phone case or cracked-screen phone protector prop (make: use an old case)", "Scissors, 1 pair", "Tape, 1 roll (make: use what you own)"], "s": ["Buy the white fabric paint. Dig the black t-shirt, black pants, and old phone case out of the closet.", "Chalk the words 'Page Not Found' on the black t-shirt first and check them in a mirror for centering and spelling. Paint or stencil over the chalk with the white fabric paint. Painted letters cannot be fixed, so the chalk draft is the step.", "Use the white fabric paint or white paper for the letters, and let the paint dry fully.", "Tape the old phone case to one hand.", "Walk around staring at the old phone case, announcing that the page cannot be found.", "Optional pro finish: draw a fake broken-image icon above the text with the white paint. The icon plus the words makes the error message unmistakable.", "Optional pro finish: draw a fake broken-image icon above the text with the white paint. The icon plus the words makes the error message unmistakable."]}, "zombie-coworker": {"m": ["Old button-down shirt you can cut up, 1 (own: from closet)", "Old tie, 1 (own: from closet)", "Pale face paint or white face powder, 1 (buy: costume aisle)", "Dark eye makeup or black eyeshadow, 1 (buy: pharmacy)", "Coffee mug, 1 (own: from home)", "Scissors, 1 pair (own: from home)"], "s": ["Buy the pale face paint and dark eye makeup.", "Pull the old button-down shirt, old tie, and coffee mug from home.", "Safety: cut away from your fingers, and keep the scissors away from small kids. Use non-toxic costume makeup.", "Decide where every slit goes and mark the spots with chalk before cutting, since cut fabric cannot be put back. Make the torn shirt: cut jagged slits along the hem of the old button-down shirt and one sleeve. Tie the old tie loosely and crookedly around the neck.", "Make the face: cover the face with the pale face paint. Ring the eyes with the dark eye makeup. Smudge a little down one cheek like a long night at the office.", "Wear the torn shirt with the loosened tie and carry the coffee mug everywhere, mumbling about the quarterly review.", "Optional pro finish: add a lanyard with a blank ID badge worn backwards, the universal sign of someone who gave up at 3pm.", "Optional pro finish: add a lanyard with a blank ID badge worn backwards, the universal sign of someone who gave up at 3pm."]}, "the-olympians": {"m": ["White bedsheets or large white fabric, 1 per person (own: raid the linen closet)", "Gold rope or gold cord, 2 yards per person (buy: craft store)", "Gold paper or gold craft leaves for laurel crowns, 1 pack (buy: craft store; gold paper works too)", "Gold face paint or gold eyeliner, 1 (buy: drugstore)", "Cardboard for the props, 3 pieces: lightning bolt, trident, owl (own: from boxes)", "Gold markers or gold paint pen, 1 (buy: craft store)", "Safety pins, 6 to 8; scissors, 1 pair; tape, 1 roll (own: household)"], "s": ["Buy the gold rope, gold paper, gold face paint, and gold markers. Pull the white bedsheets from the linen closet.", "Make the togas: wrap one sheet around each person over a plain t-shirt and shorts, pinning at the shoulder with a safety pin. Belt it with the gold rope.", "Safety: pin from the outside of the fabric so pin backs face the clothes, never the skin. Keep the toga above the ankles so nobody trips.", "Size the paper strip around each head and overlap it by an inch before taping, since tape cannot be repositioned cleanly. Make the laurel crowns: cut leaf shapes from the gold paper and tape them along a paper strip sized to each head.", "Make the god props: cut a lightning bolt, a trident, and an owl from the cardboard. Color them gold with the markers.", "Paint one gold detail on each face: a lightning streak, an owl feather, or a wave. Each god picks a power pose for the group photo.", "Optional pro finish: wrap gold cord around each wrist as a cuff and tie gold cord laces up the calves over the shoes for the sandal look.", "Optional pro finish: wrap gold cord around each wrist as a cuff and tie gold cord laces up the calves over the shoes for the sandal look."]}, "safari-photographer": {"m": ["Khaki vest with pockets, 1 (buy: thrift store, or wear a tan button-down from closet)", "Khaki pants or shorts, 1 pair (own: from closet)", "Toy camera, 1 (buy: dollar store, or make: draw a camera on cardboard and tape a strap)", "Toy binoculars, 1 (buy: dollar store; two paper towel rolls taped together work too)", "Stuffed lion or lion cub toy, 1 (buy: thrift store or toy aisle)", "Safari hat, 1 (buy: costume aisle, or wear any wide-brim hat from home)", "Scissors, 1 pair; tape, 1 roll; marker, 1 (own: household)"], "s": ["Buy or gather the toy camera, toy binoculars, stuffed lion or lion cub toy, and safari hat.", "Pull the khaki pants and khaki vest from the closet.", "Safety: cut the cardboard slowly and keep fingers clear of the scissors.", "Sketch the camera shape on the cardboard first and cut one size up, then trim down after a test fitting. To make the camera: cut a camera shape from cardboard and draw a lens with a marker. Tape a ribbon or belt through it as a strap.", "Dress in the khaki pants, khaki vest, and safari hat. Hang the toy camera around your neck and the toy binoculars over the shoulder.", "Finishing touch: tuck the stuffed lion under one arm and practice your best explorer pose.", "Optional pro finish: make a press pass on an index card (name plus STAFF PHOTOGRAPHER) and hang it from a lanyard or string.", "Optional pro finish: make a press pass on an index card (name plus STAFF PHOTOGRAPHER) and hang it from a lanyard or string."]}, "player-one-two": {"m": ["Matching t-shirts, 2, any color (buy: thrift store, or own: from closet)", "Iron-on letters or fabric markers, spelling 1 and 2 (buy: craft store)", "Toy game controllers, 2 (buy: toy store, or make: draw one on cardboard)", "Iron, 1 (own: household)"], "s": ["Buy the matching t-shirts, iron-on letters or fabric markers, and toy game controllers.", "Put a big '1' on the front and back of one t-shirt with the iron-on letters. Put a big '2' on the front and back of the other t-shirt.", "Safety: let an adult handle the hot iron on a hard surface.", "Pin or tape the letters to the shirts and check the size and position in a mirror BEFORE heating the iron, ironed letters cannot be repositioned. Iron the letters onto the t-shirts on a hard surface with an adult handling the iron, or draw them with the fabric markers.", "Each player: wear their numbered t-shirt and carry a toy game controller.", "Walk in together, controllers up, and argue good-naturedly all evening about who is really player one.", "Optional pro finish: add a small 'INSERT COIN' label under each number with a fabric marker. It is the detail that gets the laugh from anyone over thirty.", "Optional pro finish: add a small 'INSERT COIN' label under each number with a fabric marker. It is the detail that gets the laugh from anyone over thirty."]}, "dinosaur-family": {"m": ["1 green sweatsuit per person (buy: discount store, or use one you own)", "1 sheet green felt per person, 9x12 inches (buy: craft store; construction paper works too)", "Scissors, 1 pair", "Fabric glue, 1 tube, or 6 safety pins per person (buy: craft store or dollar store)", "Green face paint, non-toxic, 1 tube (buy: drugstore)"], "s": ["Buy one green sweatsuit and one sheet of green felt per person.", "Safety: adults handle the scissors when cutting the green felt.", "Trace your palm on paper first and use it as the triangle template: spikes about palm-size read best. Cut 8 to 10 triangles from the green felt per person with the scissors.", "Glue or pin the green felt triangles in a row from the hood down the back of the green sweatsuit.", "Paint green spots on each cheek with the green face paint, keeping it clear of the eyes.", "Put the green sweatsuit on over regular clothes, and pin the spikes flat to the hood so they stay put.", "Optional pro finish: cut two small white felt triangles and glue them to the hood cuffs as claws. Claws make the arms part of the costume, not just the back.", "Optional pro finish: cut two small white felt triangles and glue them to the hood cuffs as claws. Claws make the arms part of the costume, not just the back."]}, "snow-sisters": {"m": ["Icy-blue dress or blue dress plus silver glitter glue, 1 set (buy glitter glue: craft store)", "Pink or lavender dress, 1 (own)", "White shirt, white pants, 3 large black felt circles (buy felt: craft store)", "Brown clothes, 2 brown pipe cleaners, 1 red pom-pom (buy: craft store)", "Silver headband, 1 (buy: dollar store)", "Tape and scissors, 1 set (own)"], "s": ["Assign roles, then buy the silver glitter glue, black felt circles, brown pipe cleaners, red pom-pom, and silver headband.", "Pull the dresses and the white and brown clothes from closets. The snow princess just wears her dress, no crafting needed.", "Test the glitter pattern on paper first. Glued glitter cannot be repositioned. Spread the silver glitter glue in thin lines along the neckline and sleeves, and let it dry FLAT for one hour. Glue dried on a hanger drips.", "Safety: cut slowly and keep fingers clear of the scissors.", "Snowman: tape the 3 black felt circles down the front of the white shirt as coal buttons. Reindeer: twist the 2 brown pipe cleaners into antler shapes and tape them to the silver headband. Tape the red pom-pom over the nose as a glowing nose.", "Wear each outfit with its accessories. The ice queen adds the silver headband as a tiara.", "Optional pro finish: the ice queen wears the silver headband as a tiara in every photo. The tiara is what separates the ice queen from a girl in a blue dress.", "Optional pro finish: the ice queen wears the silver headband as a tiara in every photo. The tiara is what separates the ice queen from a girl in a blue dress."]}, "sushi-roll": {"m": ["White bedsheet or large white t-shirt to wear, 1 (own: from closet)", "Dark green felt, 1 large sheet (buy: craft store; construction paper works too)", "Pink or orange felt, 1 large sheet (buy: craft store)", "White pom-poms, 4 large, plus 1 green pom-pom (buy: craft store; cotton balls work too)", "Toy chopsticks, 1 pair, or 2 wooden sticks (buy: toy store or craft store; pencils work too)", "Fabric glue, 1 bottle (buy: craft store)", "Scissors, 1 pair"], "s": ["Buy the green and pink felt, the pom-poms, the toy chopsticks, and the fabric glue.", "Dress in the white bedsheet or large white t-shirt.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Wrap the felt band around the waist first and mark where it overlaps before cutting, since the band must meet around the body. Make the wrap: cut the dark green felt sheet into a wide band that goes around your waist. Glue or pin it there as the seaweed wrap.", "Make the toppings: cut the pink felt sheet into long strips and glue them across the white shirt as salmon. Glue the white pom-poms near the shoulder as rice balls and the green pom-pom as wasabi.", "Finishing touch: carry the toy chopsticks in one hand like you are about to pick up a bite.", "Optional pro finish: tie a thin red ribbon belt over the seaweed wrap like the band on a real sushi roll, and glue sesame dots (tiny white paper circles) on the salmon strips.", "Optional pro finish: tie a thin red ribbon belt over the seaweed wrap like the band on a real sushi roll, and glue sesame dots (tiny white paper circles) on the salmon strips."]}, "deviled-egg": {"m": ["1 white t-shirt (buy: craft store, or use one you own)", "1 sheet yellow felt, 9x12 inches (buy: craft store; construction paper works too)", "2 sheets red felt, 9x12 inches each (buy: craft store; construction paper works too)", "1 red headband (buy: dollar store)", "2 red pipe cleaners, 12 inches each (buy: craft store; twisted strips of red paper work too)", "Scissors, 1 pair; tape, 1 roll or glue, 1 bottle", "Red face paint or lipstick, 1 (buy: drugstore)"], "s": ["Buy the white t-shirt, yellow felt, red headband, and red pipe cleaners.", "Safety: adults handle the scissors when cutting the felt.", "Draw the egg-yolk oval on paper first and hold it against the white t-shirt to check the size, about dinner-plate size. Cut it from the yellow felt with the scissors. Cut it bigger rather than smaller: a yolk that covers the chest reads instantly.", "Tape or glue the yellow felt oval to the chest of the white t-shirt.", "Twist the two red pipe cleaners into small horns, and tape them to the red headband.", "Cut a long pointed tail from the red felt sheets with the scissors, about 18 inches long. Tape it to the back of the white t-shirt at two points, shoulder blades and lower back, so it stands up. Sit down once to make sure it clears the chair.", "Optional pro finish: cut a jagged white felt ring around the yellow yolk for the egg-white edge. The white rim is what makes it read as a fried egg instead of a yellow circle.", "Optional pro finish: cut a jagged white felt ring around the yellow yolk for the egg-white edge. The white rim is what makes it read as a fried egg instead of a yellow circle."]}, "pizza-slice": {"m": ["Large cardboard box, 1 (make: cut a big triangle, about 3 feet tall)", "Yellow and orange acrylic paint, 1 bottle each (buy: craft store)", "Red felt, 1 sheet (buy: craft store; red paper works too)", "Brown felt scraps for crust, or 1 brown paper bag (buy: craft store)", "Paintbrush, scissors, tape, 1 set (own)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Buy the yellow and orange acrylic paint, red felt, and fabric glue. Cut the big triangle from the large cardboard box with the scissors. Round off the wide end for the crust.", "Paint the whole triangle a golden yellow-orange with the paintbrush and let it dry 1 hour.", "Arrange the pepperoni on the triangle DRY first. Pepperoni clusters in the middle if you glue as you go. Cut red felt circles and glue them spread out, then add the brown crust strip along the wide end.", "Tape two string loops to the back so it wears like a sandwich board. Keep the crust at the top and the point at the bottom.", "Optional pro finish: add green felt 'peppers' and white felt 'cheese drips' along the top edge. Toppings are what separate a pizza slice from a yellow triangle.", "Optional pro finish: add green felt 'peppers' and white felt 'cheese drips' along the top edge. Toppings are what separate a pizza slice from a yellow triangle."]}, "popcorn-bucket": {"m": ["Cardboard box, 1 medium (make: tall enough to cover the torso)", "Red and white striped wrapping paper or paint, 1 roll (buy: dollar store or craft store)", "Yellow or white balloons, 8 to 10 (buy: dollar store)", "Tape, string, scissors, 1 set (own)", "Red marker for the label, 1 (own)"], "s": ["Buy the red and white striped wrapping paper and the yellow or white balloons. Wrap the cardboard box in red-and-white stripes and write 'POPCORN' big across the front with the red marker.", "Cut the head and arm holes SMALL first and test the fit. Holes cut too big cannot be shrunk. Tape the inside edges of the holes so the cardboard does not scratch.", "Blow up the yellow or white balloons and tie them in a cluster. Tie the cluster to a string ring that sits on top of the box like overflowing popcorn.", "Step into the box and pull the string straps over the shoulders. Carry the popcorn crown carefully through doorways.", "Optional pro finish: glue a few 'popcorn' pieces to the rim as if overflowing. Overflowing reads as fresh and generous; a flat top reads as empty.", "Optional pro finish: glue a few 'popcorn' pieces to the rim as if overflowing. Overflowing reads as fresh and generous; a flat top reads as empty."]}, "ice-cream-cone": {"m": ["Tan paper party hat or cone, 1 (buy: dollar store)", "White t-shirt, 1 (buy: craft store, or use one you own)", "Colored dot stickers or pom-poms for sprinkles, 1 pack (buy: craft store; cut paper dots work too)", "Brown paint or marker for the cone crosshatch, 1 (buy: craft store)", "Tape, 1 roll (own)"], "s": ["Buy the tan paper party hat, the white t-shirt, the dot stickers, and the brown marker.", "Draw a waffle-cone crosshatch on the tan paper party hat with the brown marker.", "Set the tan paper party hat on the head like a hat, and tape the elastic so it sits snugly.", "Safety: keep small pom-poms away from kids under three, since they are a choking hazard.", "Cover the white t-shirt with the colored dot stickers or pom-poms, scattered like sprinkles.", "Keep the stickers off the skin.", "Optional pro finish: add a red pom-pom 'cherry' to the tip of the hat with a dot of glue. The cherry is what makes strangers say the flavor out loud.", "Optional pro finish: add a red pom-pom 'cherry' to the tip of the hat with a dot of glue. The cherry is what makes strangers say the flavor out loud."]}, "pbj": {"m": ["Brown t-shirt, 1 (buy: thrift store, or own: from closet)", "Purple t-shirt, 1 (buy: thrift store, or own: from closet)", "White poster board, 2 sheets (buy: dollar store)", "Markers, 1 set (own: household)", "Scissors, 1 pair, and tape or string, 1 roll or spool (own: household tools)"], "s": ["Draw the bread shape on the poster board first and hold it against the t-shirt to check the size, bread cut too small looks like a badge, and poster board cut away cannot be put back. Cut two big sandwich-bread shapes from the white poster board with the scissors, cutting generous and trimming after the fitting. Buy the brown t-shirt, purple t-shirt, and white poster board if needed.", "Write 'PB' in big letters on one bread shape and 'J' on the other with the markers.", "Tape or string one bread sign to the front of the brown t-shirt. Tape or string the other to the front of the purple t-shirt.", "Stand pressed together all evening, bread sides out. The brown-shirt person is the peanut butter and the purple-shirt person is the jelly.", "Optional pro finish: draw a wavy crust edge around each bread shape with a tan marker. The crust line is what makes it read as bread instead of a white sign.", "Optional pro finish: draw a wavy crust edge around each bread shape with a tan marker. The crust line is what makes it read as bread instead of a white sign."]}, "bacon-eggs": {"m": ["Dark red or brown shirt for the bacon, 1 (own)", "White shirt for the egg, 1 (own)", "1 sheet red-brown craft felt, 9x12 inches (buy: craft store, construction paper works too)", "1 sheet each white and yellow craft felt, 9x12 inches (buy: craft store, construction paper works too)", "Safety pins, 6 to 8 (buy: dollar store)", "Scissors, 1 pair"], "s": ["Buy the craft felt and the safety pins.", "Lay out the felt on the shirts and pin the arrangement BEFORE cutting or pinning for real. Cut 4 wavy vertical strips from the red-brown craft felt with the scissors. Cut one large white oval (dinner-plate size) and one yellow circle (saucer size) from the other felt sheets.", "Pin the wavy strips down the front of the dark red or brown shirt with a safety pin.", "Pin the white oval to the white shirt, then pin the yellow circle on top of it for the yolk.", "Put on the shirts. Have the bacon stand just behind the egg for photos, yolk side out.", "Optional pro finish: cut the bacon strips with pinking shears or a wavy line instead of straight, the sizzle edge is what makes people say 'oh! bacon' instead of 'red strips'.", "Optional pro finish: cut the bacon strips with pinking shears or a wavy line instead of straight, the sizzle edge is what makes people say 'oh! bacon' instead of 'red strips'."]}, "peas-pod": {"m": ["Green t-shirts, 1 per person for 3 to 5 people (buy: thrift store, or own: from closet)", "Green felt, 1 yard (buy: craft store; green fabric works too)", "Green fabric paint, 1 bottle (buy: craft store)", "Hot glue gun or fabric glue, 1 (buy: craft store)", "Green non-toxic face paint, 1 tube (buy: drugstore)", "Scissors, 1 pair (own: household tools)"], "s": ["Lay the group out and chalk the pod outline on the felt against their actual lineup BEFORE cutting, a pod cut too short strands a pea outside, and felt cut away cannot be put back. Cut the green felt into one long pod shape with the scissors, about 6 feet long, with a pointed top, cutting long and trimming later. Buy the green felt, green fabric paint, and hot glue gun.", "Paint darker green stripes and a center seam line down the pod with the green fabric paint. Let the paint dry for 1 hour.", "Safety: let an adult handle the hot glue gun, and keep fingers away from the nozzle.", "Glue the pod to the front of the green t-shirts so it stretches across all of them. Space the wearers evenly.", "Paint a small green circle on each person's cheek with the green face paint. Line everyone up in height order under the pod and walk together in a row.", "Optional pro finish: paint each person's name on the pod next to their spot. Named peas turn a group costume into a keepsake photo.", "Optional pro finish: paint each person's name on the pod next to their spot. Named peas turn a group costume into a keepsake photo."]}, "basketball-star": {"m": ["Basketball jersey or numbered tank top, 1 (own, or buy: sporting goods store)", "Basketball shorts, 1 pair (own)", "Black non-toxic face paint or 1 eyeliner pencil (buy: toy store)", "Basketball, 1 (own, or buy: toy store)"], "s": ["Pull on the basketball jersey and the basketball shorts.", "Safety: use only the black non-toxic face paint. Skip the eye black for very young kids who will rub their eyes.", "Draw two short black stripes under each eye with the black non-toxic face paint. Keep the stripes short and below the eye, never on the eyelid, and skip them for kids who rub their eyes.", "Carry the basketball everywhere, tucked under one arm.", "Dribble it whenever you stand still.", "Optional pro finish: add a wristband and tall socks. Athletes are uniforms plus accessories; the wristband is the cheapest one.", "Optional pro finish: add a wristband and tall socks. Athletes are uniforms plus accessories; the wristband is the cheapest one."]}, "referee": {"m": ["Plain black t-shirt or long-sleeve shirt, 1 (own: from closet)", "Black pants or shorts, 1 pair (own: from closet)", "White athletic tape, 1 roll (buy: sporting goods or pharmacy)", "Plastic whistle, 1 (buy: dollar store or sporting goods)", "Yellow fabric square, 6x6 inches (own: cut from an old cloth or napkin)"], "s": ["Buy the whistle, white athletic tape, and check you have a black shirt and pants ready.", "Tear horizontal strips of the white athletic tape across the front and back of the black shirt. Space them about 2 inches apart and press firmly so they stay.", "Fold the yellow fabric square in half and tie it in a knot around the whistle lanyard. Or tape it to the whistle so it waves when you blow the whistle.", "Wear the black outfit with the striped shirt and put the whistle around your neck. Tuck the yellow flag in a pocket.", "Optional pro finish: add a black wristband on one wrist and carry the yellow flag tucked in a back pocket, hidden until the call.", "Optional pro finish: add a black wristband on one wrist and carry the yellow flag tucked in a back pocket, hidden until the call."]}, "boxer": {"m": ["Bathrobe, 1 (own)", "Toy boxing gloves, 1 pair (buy: toy store)", "Purple and yellow non-toxic face paint, 1 tube each (buy: toy store)", "Athletic shorts and sneakers, 1 set (own)", "Phone for entrance music, 1 (own)"], "s": ["Buy the toy boxing gloves and the purple and yellow non-toxic face paint.", "Pull on the athletic shorts, sneakers, and bathrobe with the hood up.", "Safety: keep the face paint clear of the eyes.", "Dab the purple and yellow face paint on one cheekbone and around one eye for bruise makeup. Less is more, one bruise reads as boxer, five bruises reads as accident. Keep all paint clear of the eyes.", "Pull on the toy boxing gloves.", "Throw a few shadow punches and play entrance music from the phone as you walk in.", "Optional pro finish: write your fighter name across the back of the robe with white duct tape letters. Walk-ins get twice the reaction when the robe has a name.", "Optional pro finish: write your fighter name across the back of the robe with white duct tape letters. Walk-ins get twice the reaction when the robe has a name."]}, "cheerleader": {"m": ["Team-color t-shirt and skirt or shorts, 1 set (own)", "4 to 6 white plastic grocery bags (make: save from home)", "Hair ribbon in a team color, 1 (buy: dollar store)", "Rubber bands or tape, 1 pack (own)", "Scissors, 1 pair"], "s": ["Safety: cut the bags up right away. Keep whole bags away from very small children.", "Stack 2 to 3 white plastic grocery bags. Cut them into long strips with the scissors, stopping 3 inches from one end, do NOT cut all the way through or the pom-pom falls apart. The uncut end becomes the handle.", "Roll the uncut end tightly and wrap it with a rubber band or tape to make a handle. Fluff the strips.", "Make a second pom-pom the same way.", "Pull on the team-color t-shirt and skirt or shorts. Tie the hair ribbon in a bow and carry a pom-pom in each hand.", "Optional pro finish: roll a sheet of paper into a cone megaphone and tape it. Shouting through a megaphone is the difference between wearing the costume and performing it.", "Optional pro finish: roll a sheet of paper into a cone megaphone and tape it. Shouting through a megaphone is the difference between wearing the costume and performing it."]}, "tennis-duo": {"m": ["White t-shirts and white shorts or skirts, 1 set each (own: from closet)", "White sweatbands, 2, or strips of white fabric (buy: sports store)", "Toy tennis rackets, 2 (buy: toy store; cardboard rackets work too)", "Tennis balls, 1 tube of 3 (buy: sports store)", "White socks and sneakers, 1 pair each (own: from closet)", "Scissors, 1 pair"], "s": ["Buy the toy tennis rackets, tube of tennis balls, and sweatbands.", "Pull the white outfits and sneakers from the closet.", "Dress head to toe in white and tie the sweatband across the forehead.", "Safety: cut the fabric slowly and keep fingers clear of the scissors.", "Measure the strip around the head with a finger's width of slack before cutting, then cut the 2-inch strip of white fabric. To make a sweatband: tie it around the head with a knot at the back, snug enough to stay but loose enough to be comfortable.", "Finishing touch: carry the toy tennis rackets and tuck the tube of balls under one arm for the courtside pose.", "Optional pro finish: add a white wristband on the racket arm and tuck one spare ball into the waistband for the between-points look.", "Optional pro finish: add a white wristband on the racket arm and tuck one spare ball into the waistband for the between-points look."]}, "bowling-pins": {"m": ["White shirt and pants per pin person, 1 set each (own)", "Red duct or electrical tape, 1 roll (buy: dollar store)", "Black shirt and pants for the bowler, 1 set (own)", "Toy bowling ball or black playground ball, 1 (buy: toy store)", "Scissors, 1 pair"], "s": ["Buy the red duct or electrical tape and the toy bowling ball.", "Measure first: the classic pin has two stripes around the neck area. Each pin person cuts two 12-inch red tape stripes from the roll with the scissors, cut all stripes before sticking any, so they match.", "Wrap two red tape stripes around the collar of the white shirt and one around each wrist.", "The bowler pulls on the black shirt and pants.", "Safety: use a lightweight toy ball, never a real bowling ball.", "Carry the toy bowling ball. Line the pins up in formation with the bowler at the end for photos.", "Optional pro finish: number the pins 1 through 10 with a black marker on the back. When the bowler 'knocks you down' you fall in number order, it gets the biggest laugh of the night.", "Optional pro finish: number the pins 1 through 10 with a black marker on the back. When the bowler 'knocks you down' you fall in number order, it gets the biggest laugh of the night."]}, "cardboard-knight": {"m": ["Large cardboard boxes, 2 to 3 (make: collect spares)", "Silver acrylic paint, 1 bottle (buy: craft store, tempera paint works too)", "Foam brush or paintbrush, 1 wide (own, or buy: craft store)", "1 pool noodle (buy: toy store or dollar store)", "Gray duct tape, 1 roll (buy: dollar store)", "Black marker, 1 (buy: dollar store)", "Scissors, 1 pair"], "s": ["Safety: an adult should handle the heavy cutting. Cut generous eye holes in the helmet so vision stays clear.", "Draw every piece on the cardboard with marker BEFORE cutting: chest plate, back plate, two shoulder pieces, helmet. Cut the helmet eye holes generously, cardboard cut away cannot be added back, and a knight who cannot see is a hazard. Cut all pieces with the scissors.", "Paint every armor piece silver with the silver acrylic paint and the foam brush. Let the paint dry fully.", "Add rivet dots and edge lines with the black marker.", "Tape the plates together with the gray duct tape so they hinge at the shoulders. Wrap the pool noodle in gray duct tape for the sword.", "Put the armor on over dark clothes once the paint is dry. Carry the noodle sword.", "Optional pro finish: tape a red crepe-paper plume to the helmet top. Knights are silver; knights with plumes are memorable.", "Optional pro finish: tape a red crepe-paper plume to the helmet top. Knights are silver; knights with plumes are memorable."]}, "ninja": {"m": ["All-black outfit: t-shirt, pants, and a black beanie, 1 set (own: from closet)", "Black belt or sash, 1 (own: an old tie or scarf)", "Black headband or strip of black t-shirt, 1 strip about 3 inches wide (own: cut from an old shirt)", "Scissors, 1 pair, and tape, 1 roll (own: household tools)", "Black non-toxic face paint for a mask stripe, 1 tube (buy: drugstore, optional)"], "s": ["Measure the strip around the forehead first and mark 3 inches wide BEFORE cutting, a strip cut too narrow digs in, and fabric cut away cannot be put back. Cut the strip a little long from the old black t-shirt with the scissors; long can be trimmed, short cannot. Put on the black beanie.", "Tie the black sash around the waist with the knot at the back, and tuck the ends in.", "Safety: keep the eyes and mouth uncovered, and wrap the black headband above the eyes.", "Wrap the black headband around the forehead and tie it at the back, leaving the eyes clear.", "Paint a thin black stripe across the bridge of the nose with the black face paint. Practice the silent sneaky walk.", "Optional pro finish: tuck the headband ends in instead of letting them dangle. Clean lines read as trained ninja; loose ends read as pirate.", "Optional pro finish: tuck the headband ends in instead of letting them dangle. Clean lines read as trained ninja; loose ends read as pirate."]}, "caped-duo": {"m": ["2 old twin sheets or large fabric rectangles, about 4x5 feet each (make: cut from old sheets)", "Craft felt for masks and emblems, 2 sheets 9x12 inches (buy: craft store, construction paper works too)", "Ribbon or cord for cape ties, about 3 feet per cape (own, or buy: craft store)", "Fabric glue, 1 tube (buy: craft store)", "Paper and pencil for sketching, 1 set (own)", "Scissors, 1 pair"], "s": ["Sketch a matching emblem for each of you on the paper.", "Cut the emblems from the craft felt with the scissors.", "Sketch and cut the emblems from paper first and hold them against the cape to check the size, emblems should cover a third of the cape width. Cut each sheet into a cape with the scissors, hem-side down. Glue a craft felt emblem to the back of each cape with the fabric glue.", "Cut two eye masks from the craft felt, cutting the eye holes wide. Glue ribbon ties to the ends with the fabric glue and let the glue dry.", "Safety: tie the cord in a loose bow that pulls free easily. Never tie anything tight around the neck. Keep the mask eye holes wide so vision stays clear.", "Tie the capes at the neck with the cord in a loose bow and put on the masks.", "Optional pro finish: cut the emblem in two felt colors, a base shape plus a smaller top shape. Layered emblems look designed; single-color looks cut-out.", "Optional pro finish: cut the emblem in two felt colors, a base shape plus a smaller top shape. Layered emblems look designed; single-color looks cut-out."]}, "hero-squad": {"m": ["Cape per person in squad colors, 1 each (buy: craft store, or make: cut from 1 yard of fabric each)", "Mask per person matching the cape color, 1 each (buy: craft store)", "T-shirt per person in the cape color, 1 each (buy: craft store)", "Fabric paint for the team emblem, 1 bottle (buy: craft store)", "Safety pins, 2 per person (own)"], "s": ["Buy the capes, masks, t-shirts, and fabric paint in the squad color.", "Sketch the team emblem on scrap paper and have the whole squad approve it BEFORE opening the paint, painted emblems cannot be unpainted. Then each hero paints the same emblem, like a lightning bolt, on the t-shirt with the fabric paint.", "Let the fabric paint dry fully before wearing.", "Safety: keep each cape short enough to clear the ground so nobody trips.", "Pin each cape at the shoulders with a safety pin, and wear the matching mask.", "End every appearance with the team pose: fists on hips, capes billowing.", "Optional pro finish: paint a matching emblem on each cape near the shoulder. Capes with emblems look designed; plain capes look borrowed.", "Optional pro finish: paint a matching emblem on each cape near the shoulder. Capes with emblems look designed; plain capes look borrowed."]}, "astronaut": {"m": ["White sweatshirt and sweatpants, 1 set (buy: clothing store, or use your own)", "1 large brown paper grocery bag (buy: grocery store or craft store)", "Silver duct tape, 1 roll (buy: dollar store)", "Flag sticker or iron-on patch, 1 (buy: craft store)", "Scissors, 1 pair"], "s": ["Buy the white sweatshirt and sweatpants, paper bag, silver duct tape, and flag sticker.", "Cut the face opening SMALLER than you think with the scissors, you can always widen it, but a too-big hole flops and ruins the bag. Hold the bag up to the face and trace the opening first.", "Wrap two silver duct tape stripes around each sleeve and pant leg. Press the flag sticker onto the chest of the sweatshirt.", "Safety: cut the face opening wide enough that vision and hearing stay clear.", "Pull on the white sweatshirt and sweatpants.", "Slip the bag over your head so the face opening lines up. Crimp the top with a strip of duct tape so it holds its shape.", "Optional pro finish: print a mission patch from home (a circle with your name and 'EST. 2026') and tape it to the opposite chest from the flag. Real astronauts wear two patches.", "Optional pro finish: print a mission patch from home (a circle with your name and 'EST. 2026') and tape it to the opposite chest from the flag. Real astronauts wear two patches."]}, "robot-ranger": {"m": ["Medium cardboard box for the torso, 1 (own: from home)", "Aluminum foil, 1 roll (buy: grocery store)", "Flexible aluminum dryer vent hose, 1 section about 3 feet (buy: hardware store)", "Sticker dots or round stickers, 1 sheet (buy: craft store; punched paper circles work too)", "Duct tape, 1 roll (buy: hardware store)", "Blue or gray sweatsuit to wear underneath, 1 set (own: from closet)", "Black marker, 1 (own: from home)", "Scissors, 1 pair"], "s": ["Buy the aluminum foil, dryer vent hose, sticker dots, and duct tape.", "Safety: cut the cardboard box slowly and keep fingers clear of the scissors. The dryer vent hose has sharp wire edges, so cut carefully and tape the ends right away.", "Before cutting, wear the box over your head and trace circles for the head and arm holes a little bigger than you need. Cut the holes SMALLER than traced first, since you can widen them but cannot shrink them. Then wrap the box in aluminum foil like a gift, taping the foil flat.", "Draw two round gauges on the foil chest with the black marker. Stick the sticker dots on as dial needles and button lights.", "Hold the hose pieces against your arms to measure the length before cutting, and cut longer than you need since cut hose cannot be repaired. The dryer vent hose has sharp wire edges, so tape the ends right away so the wire ribs stay put. Tape the top of each piece to the shoulder holes of the box so arms slide inside.", "Dress in the blue or gray sweatsuit and slide the foil-wrapped cardboard box over the head and arms. Press the sticker dials on last so they sit on the chest.", "Optional pro finish: add a big red sticker dot as an emergency button on the chest, and draw a small speaker grille under it with the black marker.", "Optional pro finish: add a big red sticker dot as an emergency button on the chest, and draw a small speaker grille under it with the black marker."]}, "penguin-huddle": {"m": ["Black long-sleeve shirts, 1 per person (buy: thrift store, or own: from closet)", "White felt, 1 sheet 9x12 inches per person (buy: craft store; white paper works too)", "Orange felt, 1 sheet 9x12 inches per person (buy: craft store; orange paper works too)", "Headbands, 1 per person (buy: dollar store)", "Fabric glue, 1 tube (buy: craft store)", "Scissors, 1 pair (own: household tools)"], "s": ["Cut one paper belly template first and check it against a shirt, a belly cut too small looks like a bib, and felt cut away cannot be put back. Then cut an oval white belly from the white felt with the scissors for each person. Buy the white felt, orange felt, headbands, and fabric glue.", "Cut a small orange triangle beak from the orange felt for each headband. Glue one beak to the front of each headband with the fabric glue.", "Glue the white bellies to the front of the black long-sleeve shirts. Let the fabric glue dry for 30 minutes.", "Each person: put on the black long-sleeve shirt and the headband with the beak. Tuck hands into the sleeves as flippers and waddle shoulder to shoulder in the huddle.", "Optional pro finish: cut two small orange felt feet shapes and tape them over the toes of dark shoes. Feet are the detail people notice in full-body photos.", "Optional pro finish: cut two small orange felt feet shapes and tape them over the toes of dark shoes. Feet are the detail people notice in full-body photos."]}, "prince-princess": {"m": ["Gold paper crown or plastic crown, 1 (buy: dollar store, or make: cut one from gold poster board)", "Cape or long piece of fabric, 1 about 3 feet long (buy: thrift store)", "Thrifted gown or long dress, 1 (buy: thrift store)", "Tiara, 1 (buy: dollar store)", "Toy scepter or wand, 1 (buy: dollar store)"], "s": ["Buy the gold paper crown, tiara, and toy scepter. Pick up the thrifted gown and cape at the thrift store.", "The prince: wear the gold paper crown and cape over dark clothes, and carry the toy scepter.", "The princess: wear the thrifted gown and tiara, and add the spare wand if there is one.", "Walk in with royal posture, wave slowly with a bent wrist, and address everyone as 'my good subject'.", "Optional pro finish: give the prince a sash of torn fabric across the chest. A sash plus a crown reads as royalty; a crown alone reads as a party hat.", "Optional pro finish: give the prince a sash of torn fabric across the chest. A sash plus a crown reads as royalty; a crown alone reads as a party hat."]}, "dino-herd": {"m": ["1 green poncho or green bedsheet per person, about 50x60 inches (buy: craft store or online)", "1 sheet green felt per person, 9x12 inches (buy: craft store; construction paper works too)", "1 old sock per person, white or colored (make: use one you own)", "Scrap fabric or cotton balls for stuffing, about 1 cup per person (make: use what you own)", "Fabric glue, 1 tube, or 6 safety pins per person (buy: craft store or dollar store)", "Scissors, 1 pair"], "s": ["Buy one green poncho and one green felt sheet per person, and raid the sock drawer for an old sock.", "Safety: adults handle the scissors when cutting the green felt.", "Cut one paper triangle first and hold it against the green poncho to check the size: palm-size works best. Cut 8 to 10 triangles from the green felt sheet per person with the scissors, all from the paper template so the row looks even.", "Pin the green felt triangles in a row down the back of the green poncho.", "Stuff the old sock with the scrap fabric, and pin the opening to the back waistband of the green poncho.", "Wear the green poncho over a t-shirt and jeans. Pin the spikes and tail flat so they do not poke anyone in a crowd.", "Optional pro finish: pin a row of small felt spikes along the sock tail too, so the tail matches the back and stops reading as a sock.", "Optional pro finish: pin a row of small felt spikes along the sock tail too, so the tail matches the back and stops reading as a sock."]}, "pixel-ghost": {"m": ["White bedsheet or white fabric, 1 twin-size (buy: thrift store)", "Black felt, 1 sheet 9x12 inches (buy: craft store; black paper works too)", "Fabric glue, 1 tube (buy: craft store)", "Scissors, 1 pair (own: household tools)", "Marker and ruler, 1 each (own: household)"], "s": ["Fold the sheet in half and chalk the zigzag line first, holding it against the wearer to check the length, a hem cut too short cannot be fixed, and this is the bottom edge of the whole costume. Cut the bottom edge into chunky square zigzags with the scissors, about 4 inches per square, cutting long and trimming later. Buy the white bedsheet and the black felt.", "Draw two square eyes and a square mouth on the black felt with the marker and ruler. Cut them out.", "Glue the felt eyes and mouth onto the top third of the white bedsheet. Let the fabric glue dry for 30 minutes.", "Safety: keep the eye area open so vision stays clear.", "Wear dark clothes underneath and drape the white bedsheet over the head with the eyes lined up. Cut two small arm slits if reaching through is hard.", "Optional pro finish: cut two small arm slits at the sides. Reaching through slits instead of lifting the whole sheet keeps the ghost shape intact all night.", "Optional pro finish: cut two small arm slits at the sides. Reaching through slits instead of lifting the whole sheet keeps the ghost shape intact all night."]}, "spaghetti-meatball": {"m": ["White t-shirt or sweatshirt, 1 (own: from closet)", "Yellow or cream yarn, 1 skein (buy: craft store)", "Brown pom-poms, 2 inch, 3 to 4 (buy: craft store)", "Fabric glue or hot glue gun, 1 (buy: craft store)", "Scissors, 1 pair"], "s": ["Lay the white shirt flat.", "Lay out the yarn strands on the shirt first WITHOUT glue to check the wavy rows cover the shirt the way you want. Then cut the yarn into 12-inch strands and glue them across the shirt in wavy rows to look like spaghetti, since glued strands cannot be repositioned.", "Glue 3-4 brown pom-poms on top as meatballs.", "Let dry completely before wearing.", "Optional pro finish: glue a few small white pom-poms among the yarn as grated parmesan, and add a red felt meatball-sauce splatter on one sleeve.", "Optional pro finish: glue a few small white pom-poms among the yarn as grated parmesan, and add a red felt meatball-sauce splatter on one sleeve."]}, "cupcake": {"m": ["Brown t-shirt or tunic for the wrapper, 1 (make: from closet)", "White pillowcase for the frosting, 1 (make: from home)", "Red pom-pom or ball for the cherry, 1 about 2 inches (buy: craft store)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Put on the brown shirt. This is the cupcake wrapper.", "Drape the white pillowcase over your head and shoulders like frosting. Mark eye positions while wearing it, take it off, and trim eye holes SMALL first, then widen. Trim the bottom edge into a wavy frosting line.", "Glue the red pom-pom on top as the cherry.", "Fluff the pillowcase edges to look like frosting swirls.", "Optional pro finish: dot the pillowcase with fabric markers in sprinkle colors before wearing. Sprinkles turn 'person in a pillowcase' into cupcake.", "Optional pro finish: dot the pillowcase with fabric markers in sprinkle colors before wearing. Sprinkles turn 'person in a pillowcase' into cupcake."]}, "banana": {"m": ["Yellow sweatshirt and sweatpants, 1 set (make: from closet, or buy: clothing store)", "Green felt, 1 sheet 9x12 inches (buy: craft store)", "Headband, 1 (buy: dollar store)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Put on the yellow sweatshirt and sweatpants.", "Cut a stem shape from green felt, about 4 inches tall.", "Hold the stem against the headband and check the position in a mirror BEFORE gluing, once fabric glue sets, the stem cannot be moved. Glue the stem to the headband and let it dry flat.", "Wear the headband. You are a banana.", "Optional pro finish: glue a small brown felt rectangle at the bottom front of the sweatshirt as the banana tip. Top and bottom details make it read as banana, not yellow sweats.", "Optional pro finish: glue a small brown felt rectangle at the bottom front of the sweatshirt as the banana tip. Top and bottom details make it read as banana, not yellow sweats."]}, "hot-dog": {"m": ["Red t-shirt, 1 (own)", "Tan or beige foam pool noodle, 1 (buy: dollar store)", "Yellow fabric paint for mustard, 1 bottle (buy: craft store)", "Safety pins or fabric glue, 1 pack (buy: craft store)"], "s": ["Put on the red shirt. You are the hot dog.", "Cut the pool noodle in half lengthwise to make two bun halves.", "Paint a thin mustard squiggle down one bun half with the yellow fabric paint. You can always add more paint, but you cannot remove it, so start thin. Let dry fully before attaching.", "Attach the bun halves to your sides with safety pins or fabric glue, one on each side.", "Optional pro finish: add a white paper vendor hat. The hat turns 'person in a bun' into a ballpark vendor, and vendors get offered tips.", "Optional pro finish: add a white paper vendor hat. The hat turns 'person in a bun' into a ballpark vendor, and vendors get offered tips."]}, "donut": {"m": ["1 large cardboard box, about 24x24 inches flat (make: from home)", "Pink paint, 1 small bottle (buy: craft store)", "Felt sprinkles, 12 to 15 small pieces, or sticker sprinkles (buy: craft store)", "Ribbon or string, 4 feet (make: from home)", "Scissors, 1 pair and glue, 1 bottle"], "s": ["Draw the donut circle on the cardboard first and check it fits over the head: outer circle about 30 inches across, center hole about 12 inches. Cut the center hole SMALLER than the head first, then widen. Cardboard cut away cannot be put back, and a too-big hole slides off the shoulders.", "Paint it pink. Let dry.", "Glue on felt sprinkles or stickers in bright colors.", "Attach ribbon to the top so you can wear it like a sandwich board.", "Optional pro finish: paint a thin brown ring around the center hole for the fried-dough edge. The brown edge is what separates donut from pink life preserver.", "Optional pro finish: paint a thin brown ring around the center hole for the fried-dough edge. The brown edge is what separates donut from pink life preserver."]}, "coffee-cup": {"m": ["White trash bag or white sheet, 1 large (make: from home)", "Cardboard tube or large cylinder, 1 (make: from home)", "Brown paper or felt for the lid, 1 sheet (buy: craft store)", "Brown marker, 1 thick (buy: dollar store)"], "s": ["Cut the arm holes first, then the head hole SMALL, stretch the bag over the head to test before cutting bigger. Cut holes in the white trash bag for head and arms with the scissors. This is the cup. A head hole cut too big slides off the shoulders.", "Draw a coffee shop logo on the front with brown marker.", "Make the lid: cut a brown paper circle bigger than your head, with a sip hole.", "Wear the bag, then the lid hat on top.", "Optional pro finish: cut a cardboard sleeve, write a coffee-shop pun on it ('Decaf? Never met her'), and tape it around the torso. The sleeve is what makes it a to-go cup instead of a white bag.", "Optional pro finish: cut a cardboard sleeve, write a coffee-shop pun on it ('Decaf? Never met her'), and tape it around the torso. The sleeve is what makes it a to-go cup instead of a white bag."]}, "salt-pepper": {"m": ["White shirt, pants, and hat for Salt, 1 set (own)", "Black shirt, pants, and hat for Pepper, 1 set (own)", "Cardboard for 2 shaker tops (make: from home)", "Gray paint or gray marker, 1 (buy: craft store)", "Black marker for the S and P, 1 (own)", "Tape or glue, 1 (own)"], "s": ["Salt dresses all in white, Pepper all in black.", "Cut two shaker tops from cardboard: a short wide cylinder or dome each, big enough to sit on a hat.", "Paint them gray and dot holes on top like a real shaker. Let dry.", "Tape each top to a hat so it rides on your head.", "Letter the caps BIG. Four-inch letters minimum, because the letter is the costume. Write a big S on Salt's shaker and a big P on Pepper's with the black marker.", "Optional pro finish: carry actual salt and pepper shakers and offer to 'season' people's costumes. The seasoning bit is the party trick, use it liberally.", "Optional pro finish: carry actual salt and pepper shakers and offer to 'season' people's costumes. The seasoning bit is the party trick, use it liberally."]}, "fruit-salad": {"m": ["Solid-color outfits in fruit colors (red, yellow, green, orange), 1 set per person (own)", "Green felt for leaf hats, 1 sheet 9x12 inches per person (buy: craft store)", "Headbands, 1 per person (buy: dollar store)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Each person picks a fruit and wears that color head to toe. Red for strawberry, yellow for banana, green for lime, orange for orange.", "Cut leaf shapes from green felt.", "Glue one leaf to each headband and let it set fully before wearing. Glued leaves cannot be repositioned, so center each leaf on the band and press for 30 seconds.", "Everyone wears their headband. Take a group photo as the fruit salad.", "Optional pro finish: snip a center vein down each felt leaf with the scissors. The vein makes flat felt read as a real leaf in photos.", "Optional pro finish: snip a center vein down each felt leaf with the scissors. The vein makes flat felt read as a real leaf in photos."]}, "wizard": {"m": ["Tall black pointy wizard hat, 1 (buy: costume aisle or craft store)", "Long plain black robe or graduation gown, 1 (own, or buy: thrift store)", "Tall straight wooden staff, about 5 feet (make: from a dowel or sturdy branch, or buy: craft store)", "Gray face paint or stick-on gray beard, 1 (buy: costume aisle, optional)", "Belt or rope sash, 1 (own)"], "s": ["Size the hat to the head BEFORE decorating, a hat decorated then found too small is heartbreaking. Put on the robe. Roll the paper into a tall wizard hat or use the store-bought one; confirm it sits without covering the eyes. Stick the star stickers on the robe and hat.", "Safety: keep the hat brim above the eyes so vision stays clear, and carry the staff upright. Never swing it at anyone.", "Draw on a gray beard with the face paint, or stick on the fake beard.", "Tie the belt or rope sash around the waist over the robe.", "Put on the pointy hat last, tap the staff on the ground, and strike a pose.", "Optional pro finish: tape a battery tea light to the wand tip. A wand that glows when you cast is the detail kids remember for years, the gasps are worth the tape.", "Optional pro finish: tape a battery tea light to the wand tip. A wand that glows when you cast is the detail kids remember for years, the gasps are worth the tape."]}, "toy-box-crew": {"m": ["Cowboy hat, 1, and cow-print vest, 1, for the sheriff (buy: costume aisle or thrift store)", "White shirt and pants, 1 set, with purple felt accents for the space ranger (own: from closet)", "Cardboard wings and 1 clear plastic dome for the space ranger helmet (own: from craft supplies)", "Brown boots or boot covers, 1 pair, for the sheriff (own: from closet)", "Yellow shirt, 1, with a hand-drawn star badge for extra toy-box friends (own: from closet)", "Toy pull-string name tags, 1 per person (own: index cards)", "Marker, 1; scissors, 1 pair; glue, 1 bottle; tape, 1 roll (own: household)"], "s": ["Buy the cowboy hat, cow-print vest, purple felt, and clear plastic dome. Pull white clothes for the space ranger, brown boots for the sheriff, and a yellow shirt for extra toy-box friends from the closet.", "Sheriff: wear the cowboy hat, cow-print vest, and brown boots. Draw a star badge on the yellow shirt with a marker.", "Lay the felt fins and buttons on the white shirt first and check the placement in a mirror before gluing, since glued felt cannot be moved. Space ranger: cut purple felt fins and buttons and glue them to the white shirt. Tape the cardboard wings to the back and wear the clear plastic dome as a helmet.", "Safety: keep the plastic dome above the shoulders with the face fully open, and carry any toy props low so nobody gets poked.", "Tie a pull-string name tag to each wrist. Strike the sheriff pose and the space-ranger landing pose for the group photo.", "Optional pro finish: draw a round speaker circle on the space ranger's chest and write PULL on it, so the pull-string joke lands without explanation.", "Optional pro finish: draw a round speaker circle on the space ranger's chest and write PULL on it, so the pull-string joke lands without explanation."]}, "demon-boy-band": {"m": ["Oversized black or white t-shirt per person, 1 each (make: from closet)", "Baggy pants per person, 1 pair each (make: from closet)", "Neon fabric paint, 1 small bottle each in 2 colors (buy: craft store)", "Temporary tattoos or 1 neon eyeliner pencil (buy: drugstore)", "Toy microphone per person, 1 each (buy: dollar store)", "Hair gel, 1 travel-size tube (make: from the bathroom)", "Sunglasses per person, 1 each, optional (make: from the drawer)"], "s": ["Buy the neon fabric paint, temporary tattoos, toy microphones, and hair gel. Lay out the matching black or white outfits.", "Decide the pattern together first and sketch it on paper, then test the neon fabric paint on an inside seam so you know how it looks. Paint matching glowing patterns on everyone: lightning marks on the sleeves, circles on the chest. Keep all paint on the clothes, off faces and away from eyes. Let the paint dry flat for 2 hours.", "Apply neon eyeliner or temporary tattoos on cheeks and hands. Style hair up and forward with the gel.", "Safety: keep paint off faces and away from eyes.", "Wear the matching streetwear, carry a toy microphone each, line up shoulder to shoulder, and strike the synchronized album-cover pose.", "Optional pro finish: give every member the same temporary tattoo on the same cheek. One matching detail is what turns matching shirts into a band.", "Optional pro finish: give every member the same temporary tattoo on the same cheek. One matching detail is what turns matching shirts into a band."]}, "dragon-rider-duo": {"m": ["1 brown t-shirt and 1 pair dark pants for the rider (make: from closet)", "Gray felt, 2 yards, or 1 old gray blanket for the dragon tunic (buy: craft store or thrift store)", "1 large cardboard box for wings and tail (make: collect spares)", "Black and yellow craft foam, 1 sheet each for the dragon eyes (buy: craft store)", "1 faux-fur vest or brown scarf for the rider (make: from closet)", "1 headband for the dragon eyes", "Scissors, tape, and string, 6 feet (make: household tools)"], "s": ["Buy the gray felt, craft foam, scissors, and tape. Pull the brown t-shirt, dark pants, and faux-fur vest from the closet.", "Draw the wing shape on paper first and hold it against the dragon person's back: wings should reach from shoulder to hip. Cut two wing shapes and a long tail from the cardboard box with the scissors. Cut the wings smaller than the paper test, not bigger: oversized cardboard wings hit every doorway. Tape all cut edges smooth before wearing.", "Glue the black and yellow foam eyes to a headband for the dragon head. The rider wears the faux-fur vest over the brown t-shirt.", "Safety: keep wing tips above waist height and tape all cardboard edges smooth so nobody gets scratched.", "Rider stands in front with arms out like steering; dragon crouches behind with wings spread. Take the flying photo.", "Optional pro finish: tape a row of small cardboard triangles along the dragon's shoulders as back ridges. Ridges plus wings read as dragon; wings alone read as bird.", "Optional pro finish: tape a row of small cardboard triangles along the dragon's shoulders as back ridges. Ridges plus wings read as dragon; wings alone read as bird."]}, "numbered-players": {"m": ["Green sweatsuit per person, 1 each (buy: thrift store, or own: from closet)", "White t-shirt per person, 1 each (own: from closet)", "Iron-on number patches or white paper numbers, 1 per person (buy: craft store)", "White sneakers, 1 pair per person (own: from closet)", "Dalgona candy or a round cookie per person, 1 each (buy: bakery, optional prop)", "Iron, 1 (own: household)"], "s": ["Buy the green sweatsuits and number patches. Pull white t-shirts and white sneakers from the closet.", "Lay the numbers on each shirt and have the wearers confirm their number BEFORE heating the iron, iron-on numbers cannot be repositioned once pressed. Iron or tape one number onto the front of each white t-shirt and the matching number on the back.", "Wear the white t-shirt under the green sweatsuit jacket with the number showing, plus the white sneakers.", "Hand each player a dalgona candy as the prop. Line up in number order for the photo.", "Safety: if using an iron, have an adult do the pressing. Keep numbers readable and identical front and back.", "Optional pro finish: draw a thin triangle border around each number with a black fabric marker. The border is what makes the number read as a player badge instead of a sticker.", "Optional pro finish: draw a thin triangle border around each number with a black fabric marker. The border is what makes the number read as a player badge instead of a sticker."]}, "emotion-crew": {"m": ["1 solid bright color outfit per person: yellow, blue, red, green, purple, or orange (make: from closet)", "Face paint matching each outfit color, 1 per person (buy: drugstore)", "1 white poster board per person (buy: dollar store)", "Markers, 1 set (make: from the house)", "Colored hair spray matching each outfit, 1 can per person, optional (buy: drugstore)"], "s": ["Pull one loud solid-color outfit per person from the closet. Buy the face paint, poster board, and markers.", "Each person picks an emotion and writes it big on poster board: Joy, Sadness, Anger, Fear, Disgust, Anxiety, Envy, Embarrassment, Ennui.", "Paint a simple face design in the matching color: a big smile, a tear, furrowed brows. Mist hair with the matching color spray if you like.", "Wear the full monochrome outfit with the emotion sign. Group up in a row like the control panel.", "Optional pro finish: paint each face design in the matching outfit color only, one color per person. Mixed colors muddy the read; monochrome reads as a character.", "Optional pro finish: paint each face design in the matching outfit color only, one color per person. Mixed colors muddy the read; monochrome reads as a character."]}, "kart-racers": {"m": ["Large cardboard box, 1 per racer, big enough to fit around the torso (make: collect spares)", "Red, blue, green, and yellow paint or wrapping paper, 1 bottle or roll per color (buy: dollar store)", "Paper plates for wheels, 4 per kart (buy: dollar store)", "Racing cap or helmet, 1 per person (own: from closet)", "Scissors, 1 pair, tape, 1 roll, and string, 1 spool (own: household tools)", "Ribbon for kart straps, about 3 feet per kart (own: from closet)"], "s": ["Buy the paint or wrapping paper and paper plates. Collect one large box per racer.", "Have each racer step inside the box first and mark where the waist sits BEFORE cutting, an opening cut too big slides down, and cardboard cut away cannot be put back. Cut the top and bottom out of each box so it fits around the torso like a kart, starting with a smaller opening and widening. Paint each kart a different bright color.", "Tape two paper-plate wheels to each side. Tape ribbon straps inside so the kart hangs at waist height.", "Safety: keep the kart box at waist height so legs move freely, and tape all cut edges smooth.", "Wear the kart with the racing cap, line up side by side, and strike the starting-grid pose.", "Optional pro finish: number each kart with a big marker digit on the front. Numbered karts turn a row of boxes into a starting grid.", "Optional pro finish: number each kart with a big marker digit on the front. Numbered karts turn a row of boxes into a starting grid."]}, "tall-hat-crew": {"m": ["Tall red-and-white striped stovepipe hat, 1 (buy: costume aisle, or make: poster board)", "Red bow tie, 1 (buy: dollar store, or make: paper)", "Black shirt and pants for the cat, 1 set (own: from closet)", "Red jumpsuits or red shirts and pants for the Things, 2 sets (own: from closet)", "Blue wigs, 2 (buy: costume aisle)", "Iron-on letters or paper that says Thing 1 and Thing 2, 1 set (buy: craft store)", "Iron, 1, and scissors, 1 pair (own: household)"], "s": ["Buy the striped hat, blue wigs, red bow tie, and iron-on letters. Pull black and red clothes from the closet.", "Cat: wear the black shirt and pants, the tall striped hat, and the red bow tie.", "Position the paper letters on each chest and check the spelling and straightness in a mirror BEFORE ironing, since iron-on letters cannot be removed. Things: wear the red jumpsuits with the blue wigs. Iron or tape Thing 1 and Thing 2 onto the chests.", "The Things bounce and cause trouble; the cat looks worried. That is the whole photo.", "Optional pro finish: add white gloves for the Things and a red ribbon tail on the cat, both cheap and both sell the characters.", "Optional pro finish: add white gloves for the Things and a red ribbon tail on the cat, both cheap and both sell the characters."]}, "chipmunk-trio": {"m": ["Red, blue, and green sweaters or sweatshirts, 1 each (buy: thrift store)", "Iron-on letters A, S, T, 1 set (buy: craft store)", "Brown felt for ears, 3 pairs worth, 1 sheet 9x12 inches (buy: craft store)", "Headbands, 3 (buy: dollar store)", "Brown eyeliner for whiskers and a nose, 1 (buy: drugstore)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Buy the sweaters, iron-on letters, brown felt, headbands, and brown eyeliner.", "Position the letters with the sweaters laid flat and have each person confirm their letter BEFORE heating the iron, iron-on letters cannot be repositioned. Iron A onto the red sweater, S onto the blue, T onto the green. Let them cool flat.", "Cut round chipmunk ears from the brown felt and glue one pair to each headband.", "Wear the letter sweaters with the ear headbands. Draw three whisker dots and a nose on each cheek with the brown eyeliner.", "Line up tallest to shortest and sing one note together for the photo.", "Optional pro finish: stuff each cheek with a cotton ball for the group photo. Chipmunk cheeks full of 'acorns' get the laugh every single time.", "Optional pro finish: stuff each cheek with a cotton ball for the group photo. Chipmunk cheeks full of 'acorns' get the laugh every single time."]}, "galaxy-knights": {"m": ["1 brown or beige bathrobe or long coat per knight (make: from closet)", "1 toy energy-blade prop per knight (buy: toy store)", "1 wide belt or rope sash per knight (make: from closet)", "1 pair dark pants and boots per knight (make: from closet)", "Brown face paint for a hood shadow, 1 tube, optional (buy: drugstore)"], "s": ["Buy the toy energy-blade props. Pull the bathrobes, belts, dark pants, and boots from the closet.", "Wear the bathrobe over dark pants with the belt tied at the waist. Pull the hood up.", "Carry the energy blade unlit until the photo. Two stances: blade up ready, or blade down calm.", "Safety: keep the toy blades pointed up or down, never at faces. Sparring stays slow and pretend.", "Line up the knights in a row, ignite the blades, and take the council photo.", "Optional pro finish: tie the belt over the robe at the natural waist and let the robe flare below it. Belted robes read as uniform; unbelted robes read as bath time.", "Optional pro finish: tie the belt over the robe at the natural waist and let the robe flare below it. Belted robes read as uniform; unbelted robes read as bath time."]}, "plastic-dream-crew": {"m": ["All-pink outfit per person: dress, suit, or sweatsuit, 1 set each (own)", "Pink sunglasses, 1 per person (buy: dollar store)", "Plastic play accessories: phone, tiara, handbag, 1 per person (own)", "Pink feather boa, 1 to share (buy: dollar store, optional)", "Blonde wig, 1 per person (buy: costume aisle, optional)"], "s": ["Pull an all-pink outfit per person from the closet. Buy the pink sunglasses and feather boa.", "Everyone wears pink head to toe with the pink sunglasses. Add the tiara, handbag, or toy phone.", "Drape the feather boa over whoever is feeling the most plastic today.", "Strike the wave-and-smile pose. Everything is pink, and that is the whole point.", "Optional pro finish: give everyone the same accessory, matching sunglasses or matching purses. Uniform accessories are what turn pink outfits into a crew.", "Optional pro finish: try the wig on for 20 minutes before the party. Itchy wigs get ripped off by nine.", "Optional pro finish: give everyone the same accessory, matching sunglasses or matching purses. Uniform accessories are what turn pink outfits into a crew.", "Optional pro finish: try the wig on for 20 minutes before the party. Itchy wigs get ripped off by nine."]}, "extinct-party-animal": {"m": ["1 jacket or blazer you own (own)", "1 sheet green craft felt, 9x12 inches (buy: craft store; construction paper works too)", "1 party hat (buy: dollar store or party aisle)", "1 blank name badge (buy: office supply aisle)", "Fabric glue, 1 tube (buy: craft store)", "Marker, 1", "Scissors, 1 pair"], "s": ["Buy the green craft felt, party hat, blank badge, and fabric glue.", "Cut one paper spike first and check the size against the jacket shoulder, about 3 inches tall. Cut 6 to 8 triangle spikes from the green craft felt with the scissors. Cut them all from the template so the row looks even.", "Glue the spikes in a row along the shoulders of the jacket. Let dry 15 minutes.", "Write 'Last seen 66 million years ago' on the badge with the marker.", "Pin on the badge, put on the party hat, and work the room.", "Optional pro finish: write 'Last seen 66 million years ago' in neat block letters on the badge. Neat handwriting sells the museum-label joke; scribble kills it.", "Optional pro finish: write 'Last seen 66 million years ago' in neat block letters on the badge. Neat handwriting sells the museum-label joke; scribble kills it."]}, "dino-tourist": {"m": ["1 Hawaiian shirt (buy: thrift store, or use your own)", "1 fanny pack (own, or buy: thrift store)", "1 plush dinosaur tail (buy: toy store or online)", "1 toy camera, optional (own)", "1 pair sunglasses, optional (own)"], "s": ["Pull the Hawaiian shirt and fanny pack from the closet.", "Clip or pin the plush tail to your waistband at the back.", "Hang the toy camera around your neck.", "Put on the sunglasses, ask strangers to take your picture, and complain about the meteor.", "Optional pro finish: tuck a folded paper map into the fanny pack and let it stick out. The map is the tourist detail people laugh at.", "Optional pro finish: tuck a folded paper map into the fanny pack and let it stick out. The map is the tourist detail people laugh at."]}, "raptor-barista": {"m": ["Green hoodie, 1 (buy: clothing store, or use your own)", "Toy T. rex arms, 1 pair (buy: toy store or online)", "Paper coffee cup, 1 (own: from home)", "Brown eyeliner pencil, 1 (own, optional)"], "s": ["Buy the green hoodie and toy T. rex arms.", "Put on the green hoodie with the hood up.", "Strap the tiny T. rex arms over your own arms at the elbows.", "Grab the paper coffee cup with the tiny arms and serve.", "Optional pro finish: write a fake coffee order on the cup in marker, like RAWR-LATTE, and tape a paper name tag to the hoodie as your barista badge.", "Optional pro finish: write a fake coffee order on the cup in marker, like RAWR-LATTE, and tape a paper name tag to the hoodie as your barista badge."]}, "emotional-support-dinosaur": {"m": ["1 vest or sleeveless jacket you own (own)", "1 sheet green craft felt, 9x12 inches (buy: craft store; construction paper works too)", "1 blank badge or pin (buy: office supply aisle)", "Fabric glue, 1 tube (buy: craft store)", "Marker, 1", "Scissors, 1 pair"], "s": ["Buy the green craft felt, blank badge, and fabric glue.", "Cut one paper spike first and hold it against the vest shoulder to check the size, about 3 inches tall. Cut 6 to 8 triangle spikes from the green craft felt with the scissors using the paper template. Uniform spikes look designed; freehand spikes look ragged.", "Glue the spikes along the vest shoulders and back. Let dry 15 minutes.", "Write 'Emotional Support Dinosaur. Do not pet.' on the badge with the marker.", "Pin it on and refuse all pets.", "Optional pro finish: write 'Emotional Support Dinosaur' in all caps on the badge, then add 'Do not pet.' underneath in smaller letters. The official-looking hierarchy sells the joke.", "Optional pro finish: write 'Emotional Support Dinosaur' in all caps on the badge, then add 'Do not pet.' underneath in smaller letters. The official-looking hierarchy sells the joke."]}, "garden-fairy": {"m": ["Pink tulle, 1 yard (buy: craft store)", "Cardboard for wings, 1 large piece about 2x3 feet (make: from a shipping box)", "Fake flowers, 1 bunch (buy: dollar store)", "Headband, 1 (buy: dollar store, or own)", "Wooden dowel or stick for the wand, about 12 inches (make: from the yard)", "Cardboard star for the wand tip, 1 (make: from scraps)", "Elastic for wing straps, about 2 feet (buy: craft store)", "Glitter glue, 1 tube (buy: craft store)", "Tape, 1 roll", "Glue, 1 bottle", "Scissors, 1 pair"], "s": ["Buy the pink tulle, fake flowers, headband, and elastic.", "Draw ONE wing on paper, cut it, and trace it flipped for the second. Symmetric wings are the fairy illusion. Cut two large wing shapes from the cardboard with the scissors.", "Cover each wing with pink tulle and tape the edges down.", "Glue fake flowers around the headband for the crown.", "Tape the cardboard star to the top of the dowel for the wand.", "Safety: keep the wand away from faces during photos.", "Tape elastic straps to the back of the wings and slip arms through.", "Optional pro finish: outline the wing edges with glitter glue and add three dots down the center. The glitter edge catches light in every photo.", "Optional pro finish: outline the wing edges with glitter glue and add three dots down the center. The glitter edge catches light in every photo."]}, "ballerina": {"m": ["Pink tulle, 2 to 3 yards (buy: craft store; about $1 a yard)", "Wide elastic, 1 inch wide, cut to the waist size plus 1 inch overlap (buy: craft store)", "Pink leotard or fitted shirt, 1 (own, or buy: clothing store)", "Pink tights, 1 pair (own, or buy: clothing store)", "Hair ties and bobby pins, 1 pack (own)", "Scissors, 1 pair"], "s": ["Measure the waist with the elastic: wrap it snug where the tutu will sit, overlap 1 inch, and cut. Tie or knot the overlap into a loop, this is the waistband. Cut it to the waist, not the hips, or the tutu slides down while twirling.", "Cut the tulle into strips about 3 inches wide and twice as long as you want the skirt. For a toddler, strips roughly 3 by 20 inches; longer for bigger kids.", "Fold one strip in half to make a loop at the top. Slip the loop under the elastic, pull the strip ends through the loop, and pull tight. Repeat side by side all the way around until the tutu looks full, usually 30 to 40 strips.", "Fluff the strips outward. Trim the bottom edge even while the tutu hangs.", "Safety: the elastic should sit snug on the waist, not the hips, so it stays up while twirling. Nothing tied around the neck.", "Wear the tutu over the leotard and tights. Pull the hair into a high bun with the hair ties and bobby pins.", "Optional pro finish: tie a short length of satin ribbon into a small bow and pin it at the back waistband. One bow is the difference between craft project and costume."]}, "butterfly": {"m": ["Large cardboard for wings, 1 sheet about 3x2 feet (make: from a shipping box)", "Acrylic paint set, 1 (buy: craft store)", "Black sweatsuit, 1 set (own, or buy: clothing store)", "Elastic for wing straps, about 2 feet (buy: craft store)", "Headband, 1 (buy: dollar store, or use your own)", "Pipe cleaners for antennae, 2 (buy: craft store)", "Tape, 1 roll", "Scissors, 1 pair"], "s": ["Buy the paint, elastic, headband, and pipe cleaners. Pull black sweats from the closet.", "Draw ONE wing on paper first, cut it out, and trace it flipped for the second, symmetric wings are the whole butterfly illusion. Cut two big wing shapes from the cardboard with the scissors following the template.", "Paint both wings with bright patterns and let them dry flat.", "Tape elastic loops to the back of each wing for the arms.", "Bend pipe cleaners into antennae and tape them to the headband.", "Safety: keep wing edges away from doorways; turn sideways to pass through.", "Wear the wings over the black sweats with the antennae headband.", "Optional pro finish: outline the wing patterns with glitter glue after the paint dries. The glitter edge catches light and photographs like real wing scales.", "Optional pro finish: outline the wing patterns with glitter glue after the paint dries. The glitter edge catches light and photographs like real wing scales."]}, "pop-star": {"m": ["Sparkly or sequin jacket, 1 (buy: thrift store)", "Toy microphone, 1 (buy: toy store or dollar store)", "Hair teasing comb, 1 (own, or buy: drugstore)", "Sunglasses, 1 pair (own, or buy: dollar store)", "Dark jeans and a dark top, 1 set (own)"], "s": ["Buy the sparkly jacket, toy microphone, and sunglasses.", "Tease the hair big with the comb.", "Safety: go easy teasing near the scalp; no pulling hard.", "Wear the sparkly jacket over the dark jeans and top.", "Put on the sunglasses.", "Carry the toy microphone everywhere and take requests.", "Optional pro finish: learn one 8-count of choreography and do it on request all night. A pop star who performs is unforgettable; one who just stands there is overdressed.", "Optional pro finish: learn one 8-count of choreography and do it on request all night. A pop star who performs is unforgettable; one who just stands there is overdressed."]}, "ice-skater": {"m": ["White dress, 1 (buy: thrift store, or own)", "White tights, 1 pair (own, or buy: clothing store)", "Hair donut for the bun, 1 (buy: drugstore)", "Blush, 1 (own, or buy: drugstore)", "Bobby pins, 1 pack (own)"], "s": ["Buy or pull the white dress, white tights, and hair donut.", "Twist the hair into a high bun around the hair donut and pin it.", "Dab a little blush on the cheeks for the cold-air glow.", "Safety: skip real skates; this costume is for dry land only.", "Wear the white dress with the tights and strike the finishing pose.", "Optional pro finish: wrap white ribbon crisscrossed up the calves over the tights. The laced calves read as skates even in sneakers.", "Optional pro finish: wrap white ribbon crisscrossed up the calves over the tights. The laced calves read as skates even in sneakers."]}, "ladybug": {"m": ["Red shirt, 1 (own)", "Black pants, 1 pair (own)", "Black felt for dots, 1 sheet 9x12 inches (buy: craft store)", "Headband, 1 (buy: dollar store)", "Black pipe cleaners for antennae, 2 (buy: craft store)", "Black pom-poms, 2 small (buy: craft store)", "Scissors, 1 pair", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Buy the black felt, headband, and pipe cleaners. Pull the red sweatsuit from the closet.", "Cut lots of circles from the black felt with the scissors.", "Arrange all the dots on the shirt DRY first and step back to check, dots cluster in the middle if you glue as you go. Cut 8 to 10 black felt circles with the scissors, arrange them spread across the red shirt, then glue.", "Cut two small wing shapes from the felt scraps, dot them, and pin them at the back.", "Bend pipe cleaners into antennae and attach them to the headband.", "Safety: pin the wings where little hands cannot reach the pins.", "Wear the dotted sweats with the antennae headband.", "Optional pro finish: paint a black center line down the back of the shirt with fabric paint. The center line splits the wings, without it, the dots read as polka dots, not ladybug.", "Optional pro finish: paint a black center line down the back of the shirt with fabric paint. The center line splits the wings, without it, the dots read as polka dots, not ladybug."]}, "daisy": {"m": ["Yellow craft foam sheets, 2 (buy: craft store)", "Brown craft foam for the flower center, 1 sheet (buy: craft store)", "Green dress, 1 (own, or buy: thrift store)", "Headband, 1 (buy: dollar store, or use your own)", "Glue, 1 tube craft glue (buy: craft store)", "Scissors, 1 pair"], "s": ["Buy the yellow and brown craft foam, headband, and glue.", "Cut 10 to 12 petal shapes from the yellow craft foam with the scissors.", "Arrange all 10 to 12 petals around the headband DRY before gluing, once craft glue sets, petals cannot be repositioned. Glue the petals in a ring around the headband, tips pointing out, overlapping slightly.", "Glue the brown foam circle in the center of the petals.", "Safety: let the glue dry fully before wearing.", "Wear the flower headband with the green dress.", "Optional pro finish: dot the brown center with yellow fabric paint dots for pollen texture. The textured center is what makes it read as a real flower up close.", "Optional pro finish: dot the brown center with yellow fabric paint dots for pollen texture. The textured center is what makes it read as a real flower up close."]}, "little-baker": {"m": ["White paper or poster board for the hat, 2 sheets (buy: craft store, or use printer paper)", "Apron, 1 (own, or buy: dollar store)", "Toy whisk, 1 (buy: toy store or dollar store)", "Flour from the kitchen, 1 pinch (optional, for the effect)", "Tape, 1 roll", "Scissors, 1"], "s": ["Buy the paper, apron, and toy whisk.", "Roll the paper into a tall chef hat shape and tape the seam.", "Measure the head with a paper strip BEFORE cutting. The hat band must fit snug or it slides over the eyes. Trim the hat band to fit the head with the scissors.", "Safety: keep real flour away from eyes; a tiny pinch on the apron only.", "Wear the hat and the apron.", "Carry the toy whisk and offer everyone imaginary cupcakes.", "Optional pro finish: dust the apron with a little flour before heading out. One flour smudge is the difference between 'dressed as a baker' and 'is a baker.'", "Optional pro finish: dust the apron with a little flour before heading out. One flour smudge is the difference between 'dressed as a baker' and 'is a baker.'"]}, "little-artist": {"m": ["Beret or flat cap, 1 (buy: thrift store)", "Cardboard for the palette, 1 piece (make: from a shipping box)", "Washable paint set, 1 (buy: craft store)", "Old smock or oversized t-shirt, 1 (own)", "Paintbrush, 1 (own, or buy: craft store)", "Scissors, 1 (own)"], "s": ["Buy the beret and the washable paint set. Pull the old smock from the closet.", "Draw the kidney-bean palette shape on the cardboard and check the size against the forearm BEFORE cutting. A palette cut too small looks like a toy. Cut it out with the scissors.", "Paint dabs of bright color around the palette edge and let dry.", "Flick a little paint onto the smock for splatters and let dry.", "Safety: use washable paint only; cover the table before splattering.", "Wear the smock and the tilted beret, and carry the palette and brush.", "Optional pro finish: squeeze real paint dabs onto the cardboard palette and carry it. A palette with actual paint on it is the prop that makes strangers say 'oh, an artist!' instead of 'nice beret.'", "Optional pro finish: squeeze real paint dabs onto the cardboard palette and carry it. A palette with actual paint on it is the prop that makes strangers say 'oh, an artist!' instead of 'nice beret.'"]}};

function esc(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;")
          .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

